/* Vragenbank PA-toets, Wft Hypothecair Krediet. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["hypothecair-krediet"] = [
["Aan welke twee maatstaven toetst de kredietgever op grond van de Tijdelijke regeling hypothecair krediet (TRHK) de maximale hypotheek?", [["De financieringslast ten opzichte van het toetsinkomen en de verhouding lening/woningwaarde (LTV)", "De TRHK begrenst de hypotheek zowel op basis van de lasten die de consument kan dragen als op basis van de waarde van de woning."], ["Het netto besteedbaar inkomen na belasting en het totale vermogen van de consument", "De TRHK werkt met een bruto toetsinkomen en financieringslastpercentages, niet met netto inkomen of vermogen."], ["De WOZ-waarde van de woning en het aantal jaren dat de consument al onafgebroken in loondienst werkt", "De WOZ-waarde is geen hoofdmaatstaf en het dienstverband is geen wettelijke leennorm; die zijn hooguit relevant voor acceptatie."], ["De koopsom van de woning en de hoogte van de NHG-kostengrens", "De koopsom en de NHG-grens bepalen niet de wettelijke leennormen; de TRHK kijkt naar lasten en woningwaarde."]]],
["Een klant kiest voor een rentevaste periode van 20 jaar. Met welke rente wordt de financieringslast volgens de TRHK berekend?", [["Met de werkelijke debetrentevoet die voor die rentevaste periode in de offerte staat", "Bij een rentevaste periode van tien jaar of langer is het renterisico beperkt en wordt getoetst op de werkelijke rente."], ["Met de door de AFM vastgestelde toetsrente, ongeacht de rentevaste periode", "De AFM-toetsrente is alleen bepalend bij een rentevaste periode korter dan tien jaar."], ["Met de gemiddelde rente van de afgelopen vijf jaar voor die rentevaste periode bij deze kredietgever", "Een historisch gemiddelde speelt geen rol in de toets; het gaat om de rente van deze lening."], ["Met de werkelijke rente verhoogd met een vaste opslag van twee procentpunt", "De TRHK kent geen vaste opslag op de werkelijke rente bij lange rentevaste perioden."]]],
["Een klant kiest een rentevaste periode van 5 jaar. De rente in de offerte is hoger dan de actuele AFM-toetsrente. Met welke rente wordt getoetst?", [["Met de offerterente, omdat bij korte rentevastperioden de hoogste van beide geldt", "Bij een rentevaste periode korter dan tien jaar geldt de hoogste van de werkelijke rente en de toetsrente; hier is dat de offerterente."], ["Met de AFM-toetsrente, omdat die bij rentevastperioden korter dan tien jaar altijd geldt", "De toetsrente is een ondergrens; ligt de werkelijke rente hoger, dan wordt met de werkelijke rente gerekend."], ["Met het gemiddelde van de offerterente en de AFM-toetsrente", "Middelen van beide rentes is niet de systematiek; de hoogste van de twee geldt."], ["Met de laagste van beide, omdat de klant daar recht op heeft", "De toets is bedoeld om renterisico op te vangen; daarom geldt juist de hoogste, niet de laagste rente."]]],
["Een deel van de gevraagde hypotheek is aflossingsvrij. Hoe wordt dit deel volgens de TRHK in beginsel meegenomen in de financieringslast?", [["Alsof het annuïtair in dertig jaar wordt afgelost", "De financieringslast wordt berekend op basis van een annuïtaire aflossing over dertig jaar, ook voor delen zonder aflossingsverplichting."], ["Alleen met de werkelijk te betalen rente, zonder aflossingscomponent", "Rekenen met alleen rente zou een te hoge leencapaciteit geven; de TRHK gaat uit van een annuïtaire last."], ["Helemaal niet, omdat er tijdens de looptijd niet op wordt afgelost", "Ook een aflossingsvrij deel brengt lasten mee en telt dus mee in de toets."], ["Alsof het lineair in twintig jaar wordt afgelost", "De TRHK rekent niet met een lineaire aflossing in twintig jaar maar met een annuïteit over dertig jaar."]]],
["Welke organisatie adviseert jaarlijks over de financieringslastpercentages die in de TRHK worden opgenomen?", [["Het Nibud", "Het Nibud berekent op basis van uitgavenpatronen welk deel van het inkomen verantwoord aan woonlasten kan worden besteed; de minister stelt de percentages vervolgens vast."], ["De Nederlandsche Bank", "DNB houdt prudentieel toezicht en stelt de financieringslastpercentages niet voor."], ["Het Kifid", "Het Kifid behandelt klachten en geschillen en adviseert niet over leennormen."], ["De Stichting Waarborgfonds Eigen Woningen", "De Stichting WEW beheert de NHG; zij stelt de wettelijke financieringslastpercentages niet voor."]]],
["Waarom rekent de TRHK met bruto woonlasten (rente en aflossing vóór belasting) en niet met netto lasten?", [["Omdat het fiscale effect van de renteaftrek al in de financieringslastpercentages zit", "De tabellen houden rekening met de belastingdruk en de aftrek, zodat de toets op bruto lasten plaatsvindt."], ["Omdat hypotheekrente sinds 2013 niet meer aftrekbaar is", "Hypotheekrente op een eigenwoningschuld is nog steeds aftrekbaar, mits aan de voorwaarden wordt voldaan."], ["Omdat de kredietgever het fiscale voordeel van de klant volgens de AVG niet mag meewegen", "De kredietgever mag fiscale informatie wel kennen en gebruiken; het netto effect zit al in de percentages."], ["Omdat netto lasten pas na de eerste aangifte inkomstenbelasting definitief vaststaan", "Netto lasten zijn vooraf goed te berekenen; de reden is dat de percentages al op bruto lasten zijn afgestemd."]]],
["Een woning staat op erfpachtgrond waarvoor jaarlijks canon wordt betaald. Hoe telt de canon mee bij de leennormen?", [["De canon telt mee als last in de financieringslast", "De TRHK rekent erfpachtcanon tot de jaarlijkse lasten, naast rente en aflossing."], ["De canon wordt opgeteld bij de woningwaarde voor de LTV", "Canon is een last en geen waardebestanddeel; erfpacht verlaagt eerder de marktwaarde."], ["De canon is alleen relevant voor de taxateur en niet voor de leennormen", "Canon raakt ook de betaalbaarheid en is daarom onderdeel van de financieringslast."], ["De canon verhoogt het toetsinkomen omdat zij fiscaal aftrekbaar is", "Canon verhoogt het toetsinkomen niet; het is juist een extra last voor de consument."]]],
["Wat houdt 'explain' bij de leennormen in?", [["De kredietgever mag verantwoord afwijken, mits gemotiveerd en vastgelegd", "De TRHK staat afwijking toe als die op basis van de persoonlijke situatie verantwoord is; de onderbouwing moet worden vastgelegd."], ["De adviseur legt de klant schriftelijk uit hoe de maximale hypotheek is berekend", "Uitleg aan de klant is goede dienstverlening, maar 'explain' is de bevoegdheid van de kredietgever om gemotiveerd af te wijken."], ["De klant mag zelf afwijken van de normen door een verklaring te tekenen", "De consument kan niet zelf de normen buiten werking stellen; de afwijking is een verantwoorde beslissing van de kredietgever."], ["De AFM keurt vooraf elke afwijking van de leennormen goed", "De AFM keurt individuele dossiers niet vooraf goed; zij houdt achteraf toezicht op het gebruik van explain."]]],
["Een klant wil zijn bestaande hypotheek oversluiten naar een lagere rente, zonder verhoging van de lening. Door een inkomensdaling past de lening niet meer binnen de huidige leennormen. Wat is juist?", [["Via explain kan de kredietgever verantwoord afwijken, omdat de klant er in lasten niet op achteruitgaat", "Oversluiten zonder verhoging waarbij de lasten dalen is een erkende situatie waarin afwijken verantwoord kan zijn, mits gemotiveerd vastgelegd."], ["Oversluiten is verboden zolang de lening niet binnen de leennormen past", "Er geldt geen absoluut verbod; juist voor deze situatie biedt explain ruimte."], ["De klant moet eerst het bedrag boven de nieuwe norm aflossen, uit eigen middelen of met een schenking", "Een verplichte aflossing is niet vereist als afwijken verantwoord is en wordt onderbouwd."], ["De leennormen gelden niet bij oversluiten binnen dezelfde geldverstrekker, ook niet als het inkomen daalt", "Ook bij een interne oversluiting is de TRHK van toepassing; afwijken gaat via explain."]]],
["De taxateur stelt de marktwaarde van een woning vast op € 350.000. De kosten koper bedragen € 15.000 en er worden geen energiebesparende voorzieningen gefinancierd. Wat is volgens de LTV-norm de maximale hypotheek?", [["€ 350.000, de kosten koper moet de klant uit eigen middelen betalen", "Bij een LTV van maximaal 100% van de marktwaarde is € 350.000 het maximum; kosten koper vallen daarbuiten."], ["€ 365.000, omdat kosten koper altijd mogen worden meegefinancierd", "Meefinancieren van kosten koper boven de marktwaarde past niet binnen de LTV-norm van 100%."], ["€ 371.000, omdat de LTV 106% van de marktwaarde mag zijn", "Een LTV van 106% gold tijdens de afbouw tot 2018; nu is de hoofdregel 100%."], ["€ 335.000, omdat de kosten koper van de marktwaarde worden afgetrokken", "De kosten koper verlagen de toegestane hypotheek niet; ze moeten alleen uit eigen middelen komen."]]],
["Een klant leent € 315.000 op een woning met een marktwaarde van € 350.000. Wat is de loan-to-value (LTV)?", [["90%", "€ 315.000 gedeeld door € 350.000 is 0,90, dus een LTV van 90%."], ["111%", "Dat is de omgekeerde verhouding (waarde gedeeld door lening), niet de LTV."], ["10%", "10% is het deel van de woningwaarde dat niet is gefinancierd, niet de LTV."], ["85%", "85% van € 350.000 is € 297.500; de lening is hoger, dus de LTV is 90%."]]],
["Wat geldt in de TRHK voor consumenten die de AOW-leeftijd hebben bereikt?", [["Voor hen gelden aparte financieringslastpercentages", "De TRHK bevat afzonderlijke tabellen voor AOW-gerechtigden, afgestemd op hun andere belastingdruk en uitgaven."], ["Zij mogen geen nieuwe hypotheek meer afsluiten", "Er geldt geen leeftijdsverbod; ook na de AOW-leeftijd kan een hypotheek verantwoord zijn."], ["Voor hen geldt altijd een maximale LTV van 50%", "De TRHK kent geen lagere LTV-grens op basis van leeftijd."], ["Hun AOW-uitkering telt niet mee als toetsinkomen", "AOW en pensioen tellen juist mee als inkomen bij de toets."]]],
["Voor wie is de Gedragscode Hypothecaire Financieringen (GHF) bindend?", [["Voor geldverstrekkers die zich via hun brancheorganisatie aan de code hebben verbonden", "De GHF is zelfregulering; zij bindt de aangesloten aanbieders, zoals banken en verzekeraars die de code onderschrijven."], ["Voor iedere consument die een hypotheek afsluit", "Een gedragscode bindt de partijen die zich eraan verbinden, niet de consument."], ["Voor alle Nederlandse notarissen bij het opstellen en passeren van hypotheekakten voor consumenten", "Notarissen hebben hun eigen beroepsregels; de GHF is gericht op geldverstrekkers."], ["Alleen voor hypotheekadviseurs met een AFM-vergunning", "De GHF is opgesteld door en voor geldverstrekkers, niet primair voor adviseurs."]]],
["De leennormen stonden vroeger in de Gedragscode Hypothecaire Financieringen. Waarom zijn ze naar regelgeving (de TRHK) overgebracht?", [["Om de normen wettelijk voor alle kredietgevers te laten gelden", "Met de TRHK gelden de normen niet alleen voor aangesloten partijen maar wettelijk voor alle aanbieders, onder toezicht van de AFM."], ["Omdat de Europese Unie Nederland verplichtte tot een LTV van 100%", "De MCD schrijft geen LTV van 100% voor; de keuze voor wettelijke normen is nationaal."], ["Omdat de GHF sindsdien alleen nog voor verzekeraars geldt", "De GHF bestaat nog en geldt nog steeds voor aangesloten banken en verzekeraars."], ["Om het Kifid de bevoegdheid te geven leennormen vast te stellen", "Het Kifid stelt geen normen vast; de normen worden door de minister vastgesteld."]]],
["Waarop ziet de huidige Gedragscode Hypothecaire Financieringen vooral?", [["Minimumeisen aan de offerte, de voorwaarden en de informatie over kosten en rente", "De GHF regelt onder meer wat in een offerte moet staan en hoe de aanbieder informeert over voorwaarden, kosten en rente."], ["De hoogte van de financieringslastpercentages per inkomensklasse", "Die percentages staan in de TRHK, niet in de GHF."], ["De fiscale voorwaarden voor aftrek van hypotheekrente", "De fiscale regels staan in de Wet IB 2001."], ["De voorwaarden voor kwijtschelding van een restschuld met NHG", "Die voorwaarden staan in de Voorwaarden & Normen van de NHG."]]],
["Bij een annuïteitenhypotheek met een gelijkblijvende rente stijgen de netto maandlasten in de loop van de tijd. Wat is daarvan de oorzaak?", [["Het rentedeel daalt, waardoor de renteaftrek en dus het fiscale voordeel afnemen", "De bruto annuïteit blijft gelijk, maar omdat het aftrekbare rentedeel daalt, stijgt de netto last."], ["Het aflossingsdeel wordt elk jaar door de geldverstrekker verhoogd volgens een vast schema", "Het aflossingsdeel groeit vanzelf binnen dezelfde bruto annuïteit; de bruto last stijgt niet."], ["De rente wordt automatisch aan de inflatie aangepast", "Bij een vaste rente vindt geen inflatiecorrectie plaats."], ["Het eigenwoningforfait daalt elk jaar mee met de resterende hypotheekschuld", "Het forfait hangt af van de WOZ-waarde, niet van de schuld."]]],
["Een klant vergelijkt een annuïtaire en een lineaire hypotheek van hetzelfde bedrag, met dezelfde looptijd en rente. Wat is juist?", [["Bij lineair betaalt hij in totaal minder rente, maar zijn de aanvangslasten hoger", "Bij lineair daalt de schuld in het begin sneller, waardoor minder rente wordt betaald; daar staan hogere startlasten tegenover."], ["Bij lineair betaalt hij over de hele looptijd meer rente, maar de aanvangslasten zijn juist lager", "Het is andersom: lineair begint hoger en kost in totaal minder rente."], ["Beide vormen kosten over de hele looptijd evenveel rente", "Omdat de schuld bij lineair sneller daalt, is de totale rente lager."], ["Alleen de annuïtaire vorm voldoet aan de fiscale aflossingseis van minimaal annuïtair in 30 jaar", "Lineair aflossen is sneller dan annuïtair en voldoet dus ook aan de aflossingseis."]]],
["Een klant sluit een lineaire hypotheek van € 240.000 af met een looptijd van 30 jaar en een rente van 4,8%. Wat is de bruto maandlast in de eerste maand?", [["€ 1.626,67", "De aflossing is € 240.000 / 360 = € 666,67 en de rente € 240.000 × 4,8% / 12 = € 960,00; samen € 1.626,67."], ["€ 1.259,20", "Dit is ongeveer de bruto annuïteit voor dezelfde lening, niet de lineaire aanvangslast."], ["€ 960,00", "Dit is alleen het rentedeel; bij lineair komt de vaste aflossing daar nog bij."], ["€ 666,67", "Dit is alleen het vaste aflossingsdeel; de rente moet er nog bij worden opgeteld."]]],
["Een klant heeft een aflossingsvrij leningdeel van € 180.000 tegen een rente van 3,9%. Wat is de bruto maandlast van dit leningdeel?", [["€ 585,00", "€ 180.000 × 3,9% = € 7.020 per jaar; gedeeld door 12 is dat € 585,00 per maand."], ["€ 702,00", "Dit is het jaarbedrag gedeeld door 10 in plaats van door 12."], ["€ 1.085,00", "Bij aflossingsvrij wordt niet afgelost; er komt dus geen aflossingsbedrag bij de rente."], ["€ 7.020,00", "Dit is de rente per jaar, niet per maand."]]],
["Wat kenmerkt een bankspaarhypotheek?", [["Er wordt gespaard op een geblokkeerde rekening die aan het einde de lening aflost", "De lening zelf is aflossingsvrij; de inleg op de geblokkeerde spaarrekening eigen woning wordt aan het einde gebruikt voor aflossing."], ["De lening wordt maandelijks lineair afgelost via een gewone, vrij opneembare bankrekening bij dezelfde bank", "Bij bankspaar wordt niet tussentijds op de lening afgelost; er wordt apart gespaard."], ["De inleg wordt belegd in fondsen naar keuze van de klant", "Dat is een beleggingshypotheek; bij bankspaar wordt gespaard tegen een rente."], ["De klant betaalt alleen rente en bouwt geen spaartegoed op", "Dat is een aflossingsvrije hypotheek zonder spaarcomponent."]]],
["Voor een kapitaalverzekering eigen woning of spaarrekening eigen woning onder het overgangsrecht geldt een bandbreedte voor de inleg. Wat houdt die in?", [["De hoogste jaarinleg is maximaal tien keer de laagste", "De bandbreedte 1:10 voorkomt dat de inleg sterk wordt geconcentreerd, als voorwaarde voor de vrijstelling."], ["De inleg moet elk jaar precies gelijk zijn", "Variatie is toegestaan, zolang de verhouding 1:10 niet wordt overschreden."], ["De inleg mag maximaal tien jaar duren", "De bandbreedte gaat over de hoogte van de inleg, niet over de duur."], ["De uitkering mag maximaal tien keer de jaarpremie bedragen", "De bandbreedte gaat over de verhouding tussen de premies onderling, niet over de uitkering."]]],
["Wat is het doel van een overbruggingskrediet bij de aankoop van een nieuwe woning?", [["Tijdelijk de overwaarde van de oude, nog onverkochte woning beschikbaar maken voor de nieuwe", "Het overbruggingskrediet financiert de periode tussen aankoop van de nieuwe en verkoop van de oude woning."], ["De kosten koper van de nieuwe woning permanent meefinancieren boven de marktwaarde van de nieuwe woning", "Een overbrugging is tijdelijk en bedoeld voor de overwaarde, niet om kosten koper blijvend te financieren."], ["De rentevaste periode van de oude hypotheek verlengen tot de verkoop", "Een overbrugging verandert niets aan de rentevaste periode van de bestaande lening."], ["Een eventuele restschuld van de oude woning blijvend financieren", "Een restschuld is geen overwaarde; een overbrugging gaat juist uit van overwaarde."]]],
["Welk risico is kenmerkend voor een beleggingshypotheek?", [["Het belegde vermogen kan aan het einde onvoldoende zijn om de lening af te lossen", "Bij tegenvallende rendementen ontstaat een tekort, waardoor aan het einde een deel van de schuld blijft staan."], ["De hypotheekrente stijgt automatisch mee met de koersen van de fondsen waarin de klant belegt", "De hypotheekrente staat los van de beleggingsresultaten."], ["De lening wordt bij koersdaling direct opeisbaar", "Een koersdaling maakt de hypotheek niet automatisch opeisbaar."], ["De klant betaalt over de looptijd dubbel overdrachtsbelasting, bij aankoop en bij aflossing", "Overdrachtsbelasting heeft niets te maken met de hypotheekvorm."]]],
["Een starter sluit in 2026 een volledig aflossingsvrije hypotheek af voor de aankoop van zijn eigen woning. Wat is het fiscale gevolg?", [["Geen eigenwoningschuld: de rente is niet aftrekbaar en de schuld valt in box 3", "Een na 2012 aangegane lening moet minimaal annuïtair in 30 jaar worden afgelost om als eigenwoningschuld te gelden."], ["De rente is aftrekbaar, maar alleen tegen het basistarief", "Het basistarief beperkt de aftrek van een eigenwoningschuld; deze lening is echter geen eigenwoningschuld."], ["De rente is de eerste tien jaar aftrekbaar en daarna niet meer, omdat er niet wordt afgelost", "Zo'n tijdelijke aftrek bestaat niet; zonder aflossingsverplichting is er geen aftrek."], ["De lening valt in box 2 omdat er niet wordt afgelost", "Box 2 gaat over aanmerkelijk belang; een niet-kwalificerende woningschuld valt in box 3."]]],
["Wat houdt het overgangsrecht voor bestaande eigenwoningschulden per 31 december 2012 in?", [["Die schulden behouden recht op renteaftrek zonder aan de aflossingseis te hoeven voldoen", "Wie op 31 december 2012 al een eigenwoningschuld had, valt voor dat bedrag niet onder de verplichting om annuïtair af te lossen."], ["Die schulden moeten alsnog vóór 2030 volledig zijn afgelost om de renteaftrek te behouden", "Het overgangsrecht kent geen verplichte aflossing vóór een bepaald jaar."], ["Die schulden zijn vanaf 2013 onbeperkt in tijd aftrekbaar", "Ook onder het overgangsrecht blijft de maximale aftrekperiode van 30 jaar gelden."], ["Die schulden mogen onbeperkt worden verhoogd met behoud van overgangsrecht", "Een verhoging na 2012 valt onder de nieuwe regels en moet aan de aflossingseis voldoen."]]],
["Een klant heeft sinds 2009 een aflossingsvrije eigenwoningschuld. In 2026 leent hij € 40.000 bij voor een verbouwing van zijn woning. Wat geldt voor de nieuwe lening als hij renteaftrek wil?", [["Het nieuwe deel moet minimaal annuïtair in 30 jaar aflossen; het oude deel mag aflossingsvrij blijven", "De verhoging valt onder de regels vanaf 2013; het bestaande bedrag houdt het overgangsrecht."], ["Het nieuwe deel mag aflossingsvrij zijn, omdat de oude lening van vóór 2013 dat ook is en zo blijft", "Het overgangsrecht geldt alleen voor de schuld die er op 31 december 2012 al was."], ["De hele lening, inclusief het oude deel, moet nu annuïtair in de resterende looptijd worden afgelost", "Het oude deel verliest het overgangsrecht niet door een aparte verhoging."], ["Rente over leningen voor een verbouwing is nooit aftrekbaar", "Een lening voor verbetering of onderhoud van de eigen woning kan een eigenwoningschuld zijn."]]],
["Een klant verkoopt zijn woning voor € 420.000 met € 12.000 verkoopkosten; zijn eigenwoningschuld is € 260.000. Hij koopt een woning van € 525.000 met € 23.000 kosten koper. Wat is de maximale nieuwe eigenwoningschuld?", [["€ 400.000", "De eigenwoningreserve is € 420.000 − € 12.000 − € 260.000 = € 148.000; de verwervingskosten zijn € 548.000; € 548.000 − € 148.000 = € 400.000."], ["€ 388.000", "Hier zijn de verkoopkosten vergeten, waardoor de eigenwoningreserve te hoog (€ 160.000) is berekend."], ["€ 377.000", "Hier zijn de kosten koper niet meegenomen in de verwervingskosten van de nieuwe woning."], ["€ 548.000", "Hier is de eigenwoningreserve genegeerd; de bijleenregeling vraagt dat de overwaarde wordt ingebracht."]]],
["Een klant verkoopt zijn woning met overwaarde en gaat huren. Vier jaar later koopt hij opnieuw een eigen woning. Wat is fiscaal juist?", [["De eigenwoningreserve is na drie jaar vervallen; de oude overwaarde hoeft niet meer te worden ingebracht", "Een eigenwoningreserve geldt drie jaar na vervreemding; daarna vervalt zij en beperkt zij de nieuwe eigenwoningschuld niet meer."], ["Hij moet de overwaarde alsnog volledig inbrengen in de nieuwe woning, ongeacht het tijdsverloop", "De eigenwoningreserve is in tijd beperkt tot drie jaar."], ["Hij heeft voor de nieuwe woning helemaal geen recht op renteaftrek meer", "Na het vervallen van de reserve kan hij een nieuwe eigenwoningschuld aangaan, mits aan de aflossingseis wordt voldaan."], ["De overwaarde wordt na drie jaar belast in box 1", "Er volgt geen belastingheffing over de overwaarde; de reserve vervalt alleen."]]],
["Welke kosten zijn bij de aankoop van een eigen woning direct aftrekbaar als financieringskosten in box 1?", [["De advies- en bemiddelingskosten voor de hypotheek", "Kosten die samenhangen met het afsluiten van de lening, zoals advies, taxatie voor de lening en de hypotheekakte, zijn aftrekbaar."], ["De overdrachtsbelasting", "Overdrachtsbelasting is een verwervingskost van de woning, geen financieringskost, en dus niet aftrekbaar."], ["De notariskosten van de leveringsakte bij de overdracht", "De leveringsakte hoort bij de verwerving van de woning; alleen de hypotheekakte is aftrekbaar."], ["De kosten van de aankoopmakelaar en de bouwkundige keuring", "Makelaarskosten zijn verwervingskosten en niet aftrekbaar als financieringskosten."]]],
["Hoe werkt het eigenwoningforfait in de inkomstenbelasting?", [["Als bijtelling in box 1, berekend als percentage van de WOZ-waarde", "Het forfait is het fiscale voordeel van het wonen in de eigen woning; aftrekbare rente en kosten worden ervan afgetrokken."], ["Als aftrekpost die het belastbaar inkomen uit werk en woning in box 1 verlaagt", "Het forfait verhoogt juist het inkomen; de rente is de aftrekpost."], ["Als gemeentelijke belasting die jaarlijks wordt geheven", "Gemeenten heffen OZB; het forfait is onderdeel van de inkomstenbelasting."], ["Als percentage van de hypotheekschuld, belast in box 3", "Het forfait hangt af van de WOZ-waarde en valt in box 1, niet in box 3."]]],
["Een klant heeft zijn hypotheek volledig afgelost en woont nog in de woning. Wat geldt voor de aftrek wegens geen of geringe eigenwoningschuld (Wet Hillen)?", [["Hij krijgt een aftrek die het forfait deels compenseert en wordt afgebouwd", "Sinds 2019 wordt de Hillen-aftrek in dertig jaar afgebouwd, waardoor een steeds groter deel van het forfait wordt belast."], ["Het eigenwoningforfait vervalt omdat er geen schuld meer is", "Het forfait blijft bestaan zolang de woning het hoofdverblijf is, ook zonder schuld."], ["Hij mag het volledige forfait voor altijd buiten de heffing laten", "Dat was het effect vóór 2019; de compensatie wordt nu afgebouwd."], ["Hij krijgt een teruggave van de rente die hij in het verleden heeft betaald", "De Wet Hillen gaat over het forfait, niet over teruggave van betaalde rente."]]],
["Een klant verhuist naar een nieuwe woning; de oude woning staat leeg en te koop. Hoe lang kan de oude woning fiscaal nog als eigen woning gelden?", [["In het jaar van leegkomen en de drie jaren daarna", "Een leegstaande woning die te koop staat en eerder hoofdverblijf was, blijft deze periode een eigen woning."], ["Alleen tot het einde van de maand van verhuizing", "De wet biedt ruimere tijd om de oude woning te verkopen."], ["Maximaal zes maanden na de verhuizing", "De termijn is het jaar van leegkomen plus drie jaar, niet zes maanden."], ["Onbeperkt, zolang de woning te koop staat", "De periode is wettelijk beperkt; daarna valt de woning in box 3."]]],
["Een klant koopt een nieuwbouwwoning die over anderhalf jaar wordt opgeleverd. Hij woont tot die tijd in een huurhuis. Wat geldt voor de renteaftrek in de periode tot oplevering?", [["De woning kan al eigen woning zijn als hij haar binnen drie jaar betrekt", "De wet geeft een tijdelijke eigenwoningstatus voor een woning in aanbouw die binnen die termijn wordt betrokken."], ["Rente is pas aftrekbaar vanaf de dag van inschrijving op het nieuwe adres", "Dankzij de regeling voor woningen in aanbouw kan de aftrek al eerder ingaan."], ["Bouwrente is nooit aftrekbaar, alleen hypotheekrente na oplevering", "Rente tijdens de bouw kan onder voorwaarden als eigenwoningrente aftrekbaar zijn."], ["De rente valt tot oplevering verplicht in box 2", "Box 2 heeft geen relatie met de eigen woning."]]],
["Wat geldt voor de rente over een restschuld na verkoop van een eigen woning?", [["Alleen bij ontstaan tussen 29-10-2012 en 31-12-2017: maximaal 15 jaar aftrek", "Deze tijdelijke regeling is beëindigd; voor later ontstane restschulden is de rente niet meer aftrekbaar."], ["Rente over iedere restschuld is altijd 30 jaar aftrekbaar", "Een restschuld is geen eigenwoningschuld; alleen de tijdelijke regeling gaf beperkte aftrek."], ["Rente over een restschuld is aftrekbaar als de klant opnieuw een woning koopt", "Een nieuwe aankoop maakt een restschuld niet tot eigenwoningschuld."], ["Rente over een restschuld is alleen aftrekbaar bij een NHG-hypotheek", "NHG kan een restschuld kwijtschelden, maar regelt geen renteaftrek."]]],
["Een klant verhoogt zijn hypotheek met € 25.000 om een auto te kopen. Hoe wordt dit leningdeel fiscaal behandeld?", [["Het deel valt in box 3, omdat het niet aan de woning is besteed", "Het bestedingsvereiste bepaalt of een lening een eigenwoningschuld is; voor een auto is dat niet zo."], ["Het deel is aftrekbaar omdat er hypotheekrecht op de woning is gevestigd", "De zekerheid is niet doorslaggevend; het gaat om waaraan het geld is besteed."], ["Het deel is aftrekbaar als het annuïtair wordt afgelost", "Ook met annuïtaire aflossing blijft het een consumptieve besteding buiten de eigenwoningregeling."], ["Het deel valt in box 2, omdat het om een vermogensbestanddeel gaat", "Box 2 gaat over aanmerkelijk belang; een schuld voor een auto valt in box 3."]]],
["Een klant koopt naast zijn hoofdverblijf een vakantiewoning, die hij met een aparte hypotheek financiert. Wat is juist?", [["De vakantiewoning en de lening vallen in box 3; de rente is niet aftrekbaar in box 1", "Alleen het hoofdverblijf kan een eigen woning zijn; een tweede woning valt in box 3."], ["Beide woningen gelden als eigen woning als hij er beide regelmatig verblijft", "Een belastingplichtige kan maar één hoofdverblijf tegelijk hebben (behoudens tijdelijke situaties)."], ["De rente op de vakantiewoning is aftrekbaar tegen het basistarief", "Dat geldt voor de eigen woning; een tweede woning valt buiten de eigenwoningregeling."], ["Over de vakantiewoning wordt eigenwoningforfait berekend", "Het forfait geldt voor de eigen woning in box 1, niet voor een tweede woning."]]],
["Een klant leent een deel van de koopsom van zijn ouders. Wat is onder meer vereist om de rente als eigenwoningrente te kunnen aftrekken?", [["Voldoen aan de aflossingseis en de leninggegevens in de aangifte vermelden", "Ook een familielening moet minimaal annuïtair in 30 jaar worden afgelost en de klant moet de leninggegevens doorgeven."], ["De lening moet bij de notaris worden vastgelegd en worden gecombineerd met een NHG-borgtocht", "NHG is geen voorwaarde voor renteaftrek op een familielening."], ["De ouders moeten een bankvergunning van DNB hebben", "Particulieren kunnen zonder vergunning incidenteel geld lenen aan hun kinderen."], ["De lening moet aflossingsvrij zijn om schenkbelasting te voorkomen", "Een aflossingsvrije familielening na 2012 voldoet juist niet aan de aflossingseis."]]],
["Twee fiscale partners bezitten samen hun eigen woning. Hoe mogen zij het saldo van eigenwoningforfait en aftrekbare kosten verdelen?", [["In elke gewenste verhouding tussen beide partners", "Fiscale partners mogen gemeenschappelijke bestanddelen, zoals het saldo eigen woning, in elke gewenste verhouding verdelen."], ["Altijd verplicht bij helfte, ongeacht wie de rente betaalt", "Verdeling bij helfte is niet verplicht voor fiscale partners."], ["Volledig bij de partner met het laagste inkomen", "Er is geen verplichting om het saldo bij de partner met het laagste inkomen te leggen."], ["Naar rato van de eigendomsverhouding in de leveringsakte", "Voor fiscale partners is de eigendomsverhouding niet bepalend voor de verdeling."]]],
["Een klant sluit een in 2016 afgesloten annuïtaire eigenwoningschuld over naar een andere geldverstrekker. Wat geldt fiscaal voor de nieuwe lening?", [["Het aflossingsschema en de resterende looptijd van de oude lening lopen door", "Bij oversluiten loopt het oorspronkelijke aflossingsschema door; de klant krijgt geen nieuwe periode van 30 jaar."], ["Er begint een nieuwe looptijd van 30 jaar voor renteaftrek", "Oversluiten geeft geen nieuwe aftrekperiode; de al verstreken looptijd telt mee."], ["De nieuwe lening mag aflossingsvrij zijn als de rente lager is", "Een lagere rente verandert niets aan de aflossingseis."], ["De nieuwe lening valt automatisch onder het overgangsrecht voor schulden van vóór 2013", "Een lening uit 2016 heeft nooit overgangsrecht gehad."]]],
["Welke organisatie verstrekt de Nationale Hypotheek Garantie?", [["De Stichting WEW", "De Stichting WEW voert de NHG uit en staat borg tegenover de geldverstrekker."], ["De Nederlandsche Bank", "DNB is toezichthouder en geeft geen hypotheekgaranties af."], ["De gemeente", "Gemeenten waren vroeger betrokken bij achtervang, maar de NHG zelf wordt door de Stichting WEW verstrekt."], ["Het Kadaster", "Het Kadaster registreert eigendom en hypotheken, maar verstrekt geen garanties."]]],
["Waarom krijgt een klant met NHG doorgaans een lagere rente?", [["Omdat de borgtocht het risico voor de geldverstrekker verkleint", "De borgtocht beperkt het verlies van de geldverstrekker bij gedwongen verkoop; dat lagere risico wordt in de rente doorgegeven."], ["Omdat de overheid een deel van de rente rechtstreeks betaalt", "Er is geen rentesubsidie; het voordeel komt voort uit het lagere risico."], ["Omdat NHG-hypotheken niet onder de TRHK vallen", "NHG-hypotheken vallen gewoon onder de TRHK, met aanvullende NHG-normen."], ["Omdat bij NHG geen hypotheekrecht wordt gevestigd", "Ook bij NHG wordt een hypotheekrecht gevestigd; NHG komt daar bovenop."]]],
["Een klant met NHG moet zijn woning gedwongen verkopen na een echtscheiding en houdt een restschuld over. Wanneer kan de Stichting WEW de restschuld kwijtschelden?", [["Bij een erkende oorzaak, mits de klant verantwoord heeft gehandeld", "Kwijtschelding is mogelijk bij oorzaken als relatie-einde, werkloosheid, arbeidsongeschiktheid of overlijden, mits de klant zich verantwoord heeft opgesteld."], ["Altijd, ongeacht de oorzaak en het gedrag van de klant", "Kwijtschelding is geen automatisme; de oorzaak en het gedrag van de klant worden beoordeeld."], ["Alleen als de klant ouder is dan de AOW-leeftijd en geen pensioenvermogen heeft", "Leeftijd is geen voorwaarde voor kwijtschelding."], ["Nooit; NHG dekt alleen de geldverstrekker en nooit de consument zelf", "NHG beschermt ook de consument, die onder voorwaarden geen restschuld hoeft te betalen."]]],
["Hoe ontwikkelt de NHG-borgtocht zich tijdens de looptijd?", [["De borgtocht daalt elke maand alsof de lening annuïtair in 30 jaar wordt afgelost", "De dekking neemt af volgens een annuïtair schema, ook als de lening in werkelijkheid anders wordt afgelost."], ["De borgtocht blijft altijd gelijk aan het oorspronkelijke leenbedrag", "De borgtocht daalt juist in de tijd."], ["De borgtocht stijgt mee met de woningwaarde", "De borgtocht volgt een vast afbouwschema, niet de woningwaarde."], ["De borgtocht vervalt automatisch na tien jaar", "De borgtocht loopt in beginsel de hele looptijd, maar daalt wel."]]],
["Hoe wordt de eenmalige borgtochtprovisie voor NHG fiscaal behandeld?", [["Als aftrekbare financieringskosten van de eigenwoningschuld", "De NHG-provisie is een kostenpost voor het verkrijgen van de lening en is daarom aftrekbaar in box 1."], ["Als verwervingskost van de woning die niet aftrekbaar is in box 1", "De provisie hoort bij de financiering, niet bij de verwerving van de woning."], ["Als premie die in box 3 wordt vrijgesteld", "Box 3 speelt hier geen rol; het gaat om aftrekbare kosten in box 1."], ["Als schenking aan de Stichting WEW, aftrekbaar als gift", "De provisie is een vergoeding voor de borgtocht, geen schenking."]]],
["Wat wordt in een taxatierapport voor hypothecaire financiering verstaan onder de marktwaarde?", [["De geschatte prijs bij verkoop tussen een bereidwillige koper en verkoper", "De marktwaarde gaat uit van een zakelijke transactie na behoorlijke marketing, waarbij partijen zonder dwang handelen."], ["Het bedrag dat bij een executieveiling van de woning minimaal wordt opgebracht", "Dat is de executiewaarde of veilingwaarde, die doorgaans lager ligt."], ["De WOZ-waarde die de gemeente heeft vastgesteld", "De WOZ-waarde is een fiscale waarde met een andere peildatum en doelstelling."], ["De koopsom uit de koopovereenkomst", "De koopsom kan afwijken van de marktwaarde; de taxateur stelt zelfstandig de waarde vast."]]],
["Wat is de rol van een validatie-instituut bij een taxatierapport?", [["Het controleert of het rapport volgens de normen is opgesteld", "Validatie toetst kwaliteit en onderbouwing van het rapport, zodat de geldverstrekker erop kan vertrouwen."], ["Het stelt zelf de definitieve woningwaarde vast", "De taxateur stelt de waarde vast; het instituut controleert het rapport."], ["Het bepaalt de hoogte van de hypotheekrente", "De rente wordt door de geldverstrekker bepaald, niet door een validatie-instituut."], ["Het voert een bouwkundige keuring van de woning uit en rapporteert de gebreken", "Validatie is een controle op het taxatierapport, geen bouwkundig onderzoek."]]],
["Een klant koopt een woning van € 300.000 en verbouwt voor € 40.000. De taxateur stelt de marktwaarde na verbouwing vast op € 350.000. Op welke waarde wordt de LTV-toets gebaseerd?", [["De marktwaarde na verbouwing van € 350.000", "Bij financiering van een verbouwing mag de marktwaarde na verbouwing als woningwaarde worden gehanteerd."], ["De koopsom van € 300.000", "De koopsom zonder verbouwing doet geen recht aan de waarde die met de verbouwing ontstaat."], ["De koopsom plus verbouwingskosten van € 340.000", "De LTV gaat uit van de getaxeerde marktwaarde, niet van de optelsom van kosten."], ["De WOZ-waarde van vóór de verbouwing", "De WOZ-waarde is niet de maatstaf voor de LTV bij deze financiering."]]],
["Waarom moet een taxateur onafhankelijk zijn van de transactie die hij taxeert?", [["Om te voorkomen dat belangen bij verkoop of financiering de waardebepaling beïnvloeden", "De geldverstrekker baseert de lening op de waarde; die moet objectief zijn vastgesteld."], ["Omdat de taxateur anders geen overdrachtsbelasting over de koopsom van de woning mag berekenen", "Taxateurs berekenen geen overdrachtsbelasting; dat doet de notaris bij de aangifte."], ["Omdat de taxateur de koopovereenkomst moet ondertekenen", "De taxateur is geen partij bij de koopovereenkomst."], ["Omdat alleen een onafhankelijke taxateur het energielabel van de woning mag registreren", "Een energielabel wordt door een erkend energieadviseur geregistreerd, los van de taxatie."]]],
["Een klant denkt dat een taxatierapport ook uitsluitsel geeft over verborgen gebreken aan de woning. Wat is juist?", [["Een taxatie is geen bouwkundige keuring; voor de bouwkundige staat is apart onderzoek nodig", "De taxateur beoordeelt de waarde en zichtbare staat op hoofdlijnen, maar doet geen diepgaand bouwkundig onderzoek."], ["Een gevalideerd taxatierapport garandeert dat er geen gebreken zijn", "Validatie gaat over de kwaliteit van het rapport, niet over de afwezigheid van gebreken."], ["De taxateur is aansprakelijk voor alle later ontdekte gebreken", "De taxateur staat niet in voor gebreken die bij een taxatie redelijkerwijs niet zichtbaar zijn."], ["De geldverstrekker vergoedt de herstelkosten als de taxateur bij de taxatie gebreken heeft gemist", "De geldverstrekker geeft geen garantie op de bouwkundige staat van de woning."]]],
["Hoe komt een hypotheekrecht op een woning tot stand?", [["Door een notariële akte die wordt ingeschreven in de openbare registers (Kadaster)", "Voor vestiging van hypotheek op een registergoed zijn een notariële akte en inschrijving in de openbare registers vereist."], ["Door ondertekening van het bindend aanbod van de geldverstrekker door de klant en eventuele partner", "Het aanbod leidt tot een kredietovereenkomst, maar vestigt nog geen hypotheekrecht."], ["Door registratie van de lening bij het BKR", "Het BKR registreert kredieten, maar vestigt geen zakelijk recht."], ["Door een onderhandse akte tussen klant en geldverstrekker, gewaarmerkt door het Kadaster", "Een onderhandse akte is onvoldoende, ook niet met een waarmerk; een notariële akte is verplicht."]]],
["Wat houdt het recht van parate executie van de hypotheekhouder in?", [["Hij mag het onderpand bij wanprestatie zelf laten verkopen zonder voorafgaand rechterlijk vonnis", "Parate executie geeft de hypotheekhouder het recht de woning via een openbare veiling bij de notaris te verkopen."], ["Hij mag de woning zelf gaan bewonen of verhuren totdat de volledige achterstand is ingelopen", "Het hypotheekrecht geeft geen recht om de woning zelf te bewonen."], ["Hij mag de rente eenzijdig verhogen bij een betalingsachterstand", "Parate executie gaat over verkoop van het onderpand, niet over rentewijzigingen."], ["Hij moet altijd eerst toestemming van de AFM vragen voordat hij het onderpand openbaar laat veilen", "De AFM speelt geen rol bij de executie van een onderpand."]]],
["Een hypotheekhouder wil een executiewoning niet veilen maar onderhands verkopen. Wat is daarvoor nodig?", [["Toestemming van de voorzieningenrechter voor de onderhandse verkoop", "Onderhandse executoriale verkoop is mogelijk als de voorzieningenrechter de koopovereenkomst goedkeurt."], ["Alleen een nieuwe taxatie door een erkend taxateur", "Een taxatie is nuttig, maar vervangt de rechterlijke toestemming niet."], ["Toestemming van de Stichting WEW, ook als de lening zonder NHG is verstrekt", "Zonder NHG heeft de Stichting WEW geen rol, en toestemming van de rechter blijft nodig."], ["Een besluit van de algemene ledenvergadering van de VvE van het appartementencomplex", "De VvE beslist niet over de executie van een appartementsrecht."]]],
["Op een woning rusten twee hypotheekrechten van verschillende geldverstrekkers. Wat bepaalt in beginsel welke hypotheek voorrang heeft bij executie?", [["Het tijdstip van inschrijving in de openbare registers", "De rangorde van hypotheken volgt in beginsel de volgorde van inschrijving; de eerste inschrijving heeft voorrang."], ["De hoogte van het geleende bedrag per hypotheekrecht", "Een hogere lening geeft geen hogere rang."], ["De hoogte van de rente en de looptijd van elke lening", "Rentehoogte speelt geen rol bij de rangorde."], ["De datum van de koopovereenkomst bij de notaris", "De koopovereenkomst bepaalt de rang van hypotheken niet."]]],
["Wat is kenmerkend voor een bankhypotheek?", [["Het dekt ook toekomstige schulden, tot het ingeschreven bedrag", "Daardoor kan binnen de inschrijving later worden bijgeleend zonder nieuwe hypotheekakte."], ["Het dekt uitsluitend de oorspronkelijke lening", "Dat beschrijft een vaste (gewone) hypotheek, niet een bankhypotheek."], ["Het kan alleen worden gevestigd door een bank, niet door een verzekeraar", "De term gaat over de reikwijdte van de zekerheid, niet over het soort geldverstrekker."], ["Het vervalt na het einde van de rentevaste periode", "Een hypotheekrecht vervalt niet door het einde van een rentevaste periode."]]],
["Een gehuwde klant is als enige eigenaar van de woning die hij met zijn echtgenote bewoont. Hij wil er een hypotheek op vestigen. Wat is juist?", [["Hij heeft toestemming van zijn echtgenote nodig", "Boek 1 BW vereist toestemming van de echtgenoot voor bezwaring van de woning die door de echtgenoten samen wordt bewoond."], ["Hij heeft geen toestemming nodig, omdat hij de enige eigenaar is", "Ook als één echtgenoot eigenaar is, is toestemming van de ander vereist voor bezwaring van de gezamenlijke woning."], ["Hij heeft altijd toestemming van de rechter nodig", "De rechter komt alleen in beeld voor vervangende toestemming als de echtgenoot zonder goede grond weigert; primair is toestemming van de echtgenoot nodig."], ["Alleen bij huwelijkse voorwaarden is toestemming nodig", "De toestemmingseis geldt ongeacht het huwelijksvermogensregime."]]],
["Wat is erfpacht volgens Boek 5 BW?", [["Een zakelijk recht om andermans onroerende zaak te gebruiken, tegen canon", "De erfpachter heeft een zelfstandig zakelijk recht op de grond van de eigenaar en betaalt daarvoor doorgaans een canon."], ["Een huurovereenkomst voor grond die jaarlijks opzegbaar is", "Erfpacht is een zakelijk recht en geen huur, en is niet zomaar jaarlijks opzegbaar."], ["Een hypotheekrecht ten gunste van de gemeente", "Erfpacht is een gebruiksrecht, geen zekerheidsrecht."], ["Het recht om eigen gebouwen in, op of boven andermans grond te hebben", "Dat is het opstalrecht, een ander zakelijk recht uit Boek 5 BW."]]],
["Wat is een belangrijk nadeel van een variabele hypotheekrente voor de consument?", [["De maandlasten kunnen bij een rentestijging direct oplopen", "Bij variabele rente draagt de consument het renterisico; stijgt de marktrente, dan stijgen de lasten."], ["Extra aflossen is bij variabele rente nooit toegestaan", "Juist bij variabele rente is boetevrij aflossen doorgaans ruim mogelijk."], ["De rente is bij variabel altijd hoger dan bij een lange rentevaste periode", "Dat hangt af van de rentestructuur; variabel is vaak juist lager."], ["Variabele rente is fiscaal niet aftrekbaar", "De aftrekbaarheid hangt niet af van de rentevorm."]]],
["Wat is een plafondrente?", [["Een variabele rente die niet boven een afgesproken maximum kan stijgen", "De klant profiteert van rentedalingen, terwijl het plafond het risico op stijging begrenst."], ["Een vaste rente die na tien jaar automatisch daalt naar het marktniveau", "Een plafondrente is variabel met een maximum, geen vaste rente met een daling."], ["De maximale rente die de AFM jaarlijks voor alle hypotheken vaststelt", "De AFM stelt geen maximumrente voor hypotheken vast; het plafond is een productafspraak."], ["Een rente die gelijk is aan de wettelijke rente", "De wettelijke rente geldt bij betalingsachterstanden en staat los van de plafondrente."]]],
["Tussen het uitbrengen van de offerte en het passeren van de akte daalt de hypotheekrente. Welke productvoorwaarde zorgt ervoor dat de klant van die daling profiteert?", [["Een rentedaalgarantie (rentepluk)", "Daarmee krijgt de klant bij passeren de laagste rente uit de periode tussen offerte en passeren."], ["Rentemiddeling bij oversluiten", "Rentemiddeling betreft het verwerken van een boete bij tussentijds oversluiten in een nieuwe rente."], ["Een plafondrente op de lening", "Een plafond begrenst een variabele rente naar boven, maar geeft geen recht op een lagere offerterente."], ["Een verlengde rentevaste periode", "Een langere rentevaste periode verandert niets aan rentedalingen in de offerteperiode."]]],
["Veel geldverstrekkers werken met risico-opslagen per LTV-klasse. Wat kan een klant doen als zijn woning flink in waarde stijgt?", [["Een nieuwe waardering laten doen voor een mogelijk lagere risico-opslag", "Een lagere LTV betekent minder risico voor de geldverstrekker; afhankelijk van de voorwaarden kan de opslag dalen."], ["Een hogere renteaftrek aanvragen bij de Belastingdienst", "De woningwaarde heeft geen invloed op de hoogte van de aftrekbare rente."], ["Zijn rentevaste periode kosteloos laten verlengen tot dertig jaar tegen dezelfde rente", "Een waardestijging geeft geen recht op kosteloze verlenging van de rentevaste periode tegen dezelfde rente."], ["De NHG-borgtocht laten verhogen tot de nieuwe waarde", "De NHG-borgtocht volgt een vast afbouwschema en wordt niet verhoogd bij waardestijging."]]],
["Een klant met een krap budget wil zekerheid over zijn maandlasten. Waarom past een lange rentevaste periode vaak bij hem?", [["Omdat zijn lasten langdurig vaststaan en hij minder kwetsbaar is voor rentestijgingen", "Een lange rentevaste periode beperkt het renterisico, wat belangrijk is als een lastenstijging niet kan worden opgevangen."], ["Omdat de rente bij een lange rentevaste periode altijd het laagst is van alle looptijden", "Een langere rentevaste periode heeft vaak juist een hogere rente; het voordeel is zekerheid."], ["Omdat hij dan nooit een vergoeding bij vervroegde aflossing hoeft te betalen, ook niet bij verhuizing", "Ook bij een lange rentevaste periode kan bij extra aflossing boven de boetevrije ruimte een vergoeding verschuldigd zijn."], ["Omdat hij dan geen kredietwaardigheidstoets hoeft te ondergaan", "De toets geldt altijd; alleen de toetsrente kan verschillen."]]],
["Wat is volgens de Wft de maximale vergoeding die een kredietgever mag vragen bij vervroegde aflossing van een hypotheek?", [["Niet meer dan het financiële nadeel dat de kredietgever door de vervroegde aflossing lijdt", "De vergoeding is een compensatie voor renteverlies en mag het werkelijke nadeel niet overstijgen."], ["Een vast percentage van de oorspronkelijke hoofdsom, ongeacht de marktrente en de resterende rentevaste periode", "Een vast percentage los van het werkelijke nadeel is niet toegestaan."], ["De volledige rente over de resterende looptijd van de lening", "Dat zou veel hoger zijn dan het werkelijke nadeel."], ["Het bedrag dat de klant met de oversluiting bespaart", "De besparing van de klant is niet de maatstaf; het gaat om het nadeel van de kredietgever."]]],
["Een klant wil zijn hypotheek tussentijds volledig aflossen. De huidige marktrente voor de resterende rentevaste periode is hoger dan zijn contractrente. Wat is in beginsel juist?", [["Er is geen vergoeding verschuldigd, omdat de kredietgever geen renteverlies lijdt", "De kredietgever kan het geld tegen een hogere rente opnieuw uitlenen; er is dus geen financieel nadeel."], ["Hij betaalt de volledige vergoeding, omdat hij binnen de rentevaste periode aflost", "Zonder nadeel voor de kredietgever mag geen vergoeding worden gevraagd."], ["De kredietgever moet hem een vergoeding voor het renteverschil betalen", "De kredietgever is niet verplicht de klant te vergoeden voor een hogere marktrente."], ["Aflossen is niet toegestaan zolang de rente hoger ligt", "De consument heeft altijd het recht om vervroegd af te lossen."]]],
["Van welke factoren hangt de hoogte van de vergoeding bij vervroegde aflossing vooral af?", [["Het renteverschil, de resterende rentevaste periode en het bedrag boven de boetevrije ruimte", "Hoe groter het renteverschil, hoe langer de resterende periode en hoe hoger het boeteplichtige bedrag, des te hoger de vergoeding."], ["De WOZ-waarde van de woning, het energielabel en de leeftijd van de klant bij het oversluiten", "Deze factoren bepalen de vergoeding niet."], ["Het inkomen van de klant, de woningwaarde en het aantal al betaalde maandtermijnen", "Inkomen speelt geen rol, en het gaat om de resterende rentevaste periode in plaats van de betaalde termijnen."], ["De hoogte van de oorspronkelijke advieskosten en notariskosten", "Afsluitkosten van destijds zijn niet bepalend voor de vergoeding."]]],
["De rentevaste periode van een klant loopt af. Hij wil op de renteherzieningsdatum volledig oversluiten naar een andere geldverstrekker. Wat geldt voor een vergoeding wegens vervroegde aflossing?", [["Er is geen vergoeding verschuldigd, omdat de rentevaste periode is afgelopen", "Op de renteherzieningsdatum eindigt de renteafspraak; er is dan geen renteverlies te vergoeden."], ["Hij betaalt een vergoeding over de volgende rentevaste periode, berekend over de resterende hoofdsom", "Een nieuwe periode is nog niet afgesproken, dus daarover is geen vergoeding verschuldigd."], ["Hij betaalt altijd een vaste vergoeding van één maand rente", "Er is geen wettelijke vaste vergoeding bij aflossing op de herzieningsdatum."], ["Hij mag pas boetevrij oversluiten als de looptijd van 30 jaar volledig is verstreken", "Oversluiten op de renteherzieningsdatum is gewoon mogelijk."]]],
["Een klant sluit zijn eigenwoningschuld over naar een lagere rente en betaalt daarbij een vergoeding wegens vervroegde aflossing. Hoe wordt die vergoeding fiscaal behandeld?", [["Als aftrekbare kosten van de eigenwoningschuld", "Een boete bij oversluiten van een eigenwoningschuld is aftrekbaar als financieringskosten."], ["Als niet-aftrekbare verwervingskost van de woning", "De vergoeding hangt samen met de financiering, niet met de verwerving van de woning."], ["Als schuld in box 3", "De vergoeding is een kostenpost, geen schuld; zij is aftrekbaar in box 1."], ["Als inkomen dat bij de geldverstrekker belastingvrij is", "Wat de geldverstrekker met de vergoeding doet, bepaalt de fiscale positie van de klant niet."]]],
["Wat is het ESIS bij hypothecair krediet?", [["Een Europees standaardinformatieblad over het aangeboden krediet", "Het ESIS komt voort uit de hypothekenrichtlijn en maakt aanbiedingen vergelijkbaar door een vaste opbouw."], ["Een Europees register van hypotheken met betalingsachterstanden bij consumenten", "Het ESIS is geen register; registratie van achterstanden gebeurt in Nederland bij het BKR."], ["Een fiscaal formulier voor de aangifte van hypotheekrente", "Het ESIS is precontractuele informatie, geen belastingformulier."], ["Een certificaat waarmee de adviseur zijn vakbekwaamheid aantoont", "Vakbekwaamheid blijkt uit Wft-diploma's en PE, niet uit het ESIS."]]],
["Wanneer moet de consument het ESIS uiterlijk ontvangen?", [["Tijdig voordat hij gebonden is aan een kredietovereenkomst of aanbod", "De consument moet de informatie kunnen vergelijken en overwegen voordat hij zich bindt."], ["Pas na het passeren van de hypotheekakte", "Na het passeren is het te laat om de informatie te gebruiken bij de keuze."], ["Binnen een jaar na het afsluiten, bij de eerste jaaropgave van de geldverstrekker", "Het ESIS is precontractueel en hoort vóór de binding te worden verstrekt."], ["Alleen als de consument er uitdrukkelijk om vraagt", "Verstrekking is een verplichting voor de aanbieder, niet afhankelijk van een verzoek."]]],
["Wat drukt het jaarlijks kostenpercentage (JKP) uit dat in het ESIS staat?", [["De totale kosten van het krediet als percentage per jaar", "Het JKP omvat rente en bijkomende kosten, zodat aanbiedingen beter vergelijkbaar zijn."], ["Alleen de nominale debetrente op jaarbasis", "Het JKP omvat meer dan de rente, zoals verplichte bijkomende kosten."], ["Het percentage van het inkomen dat aan woonlasten opgaat", "Dat is de financieringslast, geen JKP."], ["Het deel van de woningwaarde dat wordt gefinancierd", "Dat is de LTV, geen kostenpercentage."]]],
["Welke informatie hoort onder meer in het ESIS te staan?", [["De voorwaarden en mogelijke kosten van vervroegde aflossing", "Het ESIS bevat een vast onderdeel over het recht op vervroegde aflossing en de vergoeding die daarbij kan gelden."], ["Het advies van de adviseur over de best passende verzekering", "Het ESIS beschrijft het krediet; het advies wordt apart vastgelegd."], ["De WOZ-beschikking van de gemeente", "De WOZ-beschikking is geen onderdeel van het ESIS."], ["De uitkomst van de BKR-toets van de partner", "Persoonlijke toetsingsresultaten zijn geen standaardonderdeel van het ESIS."]]],
["Een klant heeft een tijdelijk arbeidscontract. Welke verklaring van de werkgever maakt het voor geldverstrekkers doorgaans mogelijk dit inkomen volledig als vast inkomen mee te nemen?", [["Een werkgeversverklaring met een intentie tot een vast contract", "Met een intentieverklaring wordt het tijdelijke dienstverband behandeld als vast inkomen voor de toets."], ["Een verklaring dat de werknemer goed functioneert en zijn proeftijd heeft doorstaan", "Een functioneringsoordeel zonder intentie voor een vast contract is meestal onvoldoende."], ["Een salarisstrook van de laatste maand", "Een salarisstrook toont het inkomen, maar zegt niets over de duurzaamheid ervan."], ["Een verklaring van de vakbond over de cao-lonen", "De vakbond kan niets verklaren over de duurzaamheid van dit specifieke dienstverband."]]],
["Wat is een perspectiefverklaring?", [["Een verklaring over het arbeidsmarktperspectief van een flexwerker", "Een perspectiefverklaring kan het mogelijk maken een hypotheek te verkrijgen als er geen intentieverklaring van de werkgever is."], ["Een verklaring van de geldverstrekker over de verwachte renteontwikkeling", "De perspectiefverklaring gaat over het inkomen van de klant, niet over de rente."], ["Een verklaring van de taxateur over de verwachte waardestijging", "Waardeverwachtingen zijn geen basis voor deze verklaring en ook niet voor de kredietwaardigheidstoets."], ["Een verklaring van het UWV over een lopende WW-uitkering", "Een WW-uitkering is geen arbeidsmarktperspectief en het UWV geeft deze verklaring niet af."]]],
["Wat is Inkomensbepaling Loondienst (IBL)?", [["Een methode om het toetsinkomen te bepalen met UWV-gegevens", "IBL gebruikt het verzekeringsbericht van het UWV om het inkomen over de afgelopen periode vast te stellen."], ["Een fiscale regeling om hypotheekrente via de loonheffing te verrekenen", "Dat is de voorlopige aanslag of teruggaaf, geen inkomensbepaling voor de hypotheek."], ["Een verplichte verzekering tegen inkomensverlies bij werkloosheid", "IBL is geen verzekering, maar een rekenmethode voor het inkomen."], ["Een inkomensverklaring voor zelfstandig ondernemers", "IBL is bedoeld voor werknemers in loondienst; voor ondernemers gelden andere methoden."]]],
["Een zelfstandig ondernemer vraagt een hypotheek aan. Hoe wordt zijn inkomen doorgaans vastgesteld?", [["Op basis van cijfers over meerdere jaren of een inkomensverklaring", "Bij ondernemers wordt gekeken naar de resultaten over meerdere jaren, omdat het inkomen kan schommelen."], ["Alleen op basis van de omzet van de laatste maand", "Eén maand omzet zegt weinig over het duurzame inkomen."], ["Op basis van een werkgeversverklaring die hij zelf ondertekent", "Een ondernemer kan geen werkgeversverklaring over zichzelf afgeven als bewijs van inkomen."], ["Op basis van het verwachte inkomen uit zijn ondernemingsplan", "Verwachtingen zonder historie zijn doorgaans onvoldoende om verantwoord krediet te verstrekken."]]],
["Een klant betaalt partneralimentatie aan zijn ex-echtgenote. Hoe telt dit mee bij de bepaling van de maximale hypotheek?", [["De betaalde partneralimentatie verlaagt het toetsinkomen", "De TRHK brengt betaalde partneralimentatie in mindering op het toetsinkomen, omdat het een structurele verplichting is."], ["De partneralimentatie verhoogt het toetsinkomen omdat zij fiscaal aftrekbaar is", "Aftrekbaarheid maakt de alimentatie niet tot extra inkomen; het blijft een last."], ["De partneralimentatie speelt geen rol bij de leennormen", "Alimentatie drukt op de betaalcapaciteit en wordt dus meegenomen."], ["De partneralimentatie wordt bij de woningwaarde opgeteld", "Alimentatie heeft geen relatie met de woningwaarde."]]],
["Een klant heeft een studieschuld bij DUO. Wat is juist voor de hypotheekaanvraag?", [["De studieschuld telt mee als verplichting en verlaagt de hypotheek", "Een studieschuld is een financiële verplichting die de leencapaciteit verlaagt, ook al staat zij niet bij het BKR."], ["Een studieschuld telt niet mee omdat zij niet bij het BKR geregistreerd staat", "Ook zonder BKR-registratie moet de studieschuld worden meegewogen."], ["Een studieschuld moet vóór aankoop volledig zijn afgelost", "Volledige aflossing is niet verplicht; de schuld wordt wel meegewogen."], ["Een studieschuld verhoogt de maximale LTV", "Een schuld verhoogt de toegestane LTV niet."]]],
["Bij een BKR-toetsing blijkt dat een klant een doorlopend krediet heeft. Wat doet de kredietgever daarmee?", [["Hij neemt de last van het krediet mee als financiële verplichting", "Lopende kredieten drukken op de betaalcapaciteit en verlagen daardoor de maximale hypotheek."], ["Hij negeert het krediet zolang er geen achterstand bij het BKR is geregistreerd", "Ook zonder achterstand is het krediet een verplichting die meeweegt."], ["Hij verhoogt het toetsinkomen met de kredietlimiet", "Een kredietlimiet is geen inkomen."], ["Hij moet de aanvraag altijd afwijzen", "Een lopend krediet is geen automatische afwijzingsgrond."]]],
["Welk inkomensbestanddeel telt bij een werknemer in loondienst in beginsel mee in het bruto toetsinkomen?", [["Het vakantiegeld", "Het toetsinkomen is het bruto jaarinkomen inclusief vaste componenten zoals vakantietoeslag."], ["Een eenmalige bonus zonder structureel karakter", "Incidentele beloningen zijn niet duurzaam en tellen in beginsel niet mee."], ["De verwachte loonsverhoging over drie jaar", "Toekomstige verhogingen zijn onzeker en tellen niet mee als inkomen."], ["De teruggave van hypotheekrenteaftrek", "Het fiscale voordeel zit al in de financieringslastpercentages en wordt niet bij het inkomen opgeteld."]]],
["Een stel koopt een woning; alleen partner A heeft inkomen. Wat is het belangrijkste doel van een overlijdensrisicoverzekering in het advies?", [["Zorgen dat de partner na overlijden van A de lasten kan dragen", "De dekking wordt zo bepaald dat de schuld na overlijden zo ver daalt dat de lasten bij het inkomen van de nabestaande passen."], ["Zorgen dat de hypotheekrente na overlijden aftrekbaar blijft", "De renteaftrek hangt niet af van een overlijdensrisicoverzekering."], ["De NHG-kostengrens verhogen", "Een verzekering heeft geen invloed op de NHG-kostengrens."], ["Voldoen aan de fiscale aflossingseis voor de lening", "De aflossingseis heeft betrekking op de lening, niet op een verzekering."]]],
["Een werknemer in loondienst wordt langdurig ziek. Hoe verloopt zijn inkomen in hoofdlijnen?", [["Twee jaar loondoorbetaling, daarna mogelijk een lagere WIA-uitkering", "Na de loondoorbetalingsperiode kan het inkomen sterk dalen; dat moet in het hypotheekadvies worden doorgerekend."], ["Hij houdt tot zijn pensioen zijn volledige salaris via de werkgever", "De loondoorbetaling bij ziekte is beperkt tot twee jaar."], ["Hij krijgt direct een WW-uitkering van het UWV", "WW is voor werkloosheid, niet voor ziekte bij een lopend dienstverband."], ["De NHG neemt de maandlasten over vanaf de eerste ziektedag", "NHG betaalt geen maandlasten; zij kan alleen bij gedwongen verkoop een rol spelen."]]],
["Een zzp'er sluit een hypotheek af. Wat is in het advies over arbeidsongeschiktheid bijzonder aandachtspunt?", [["Hij heeft geen WIA-dekking en is aangewezen op eigen voorzieningen", "Zelfstandigen vallen niet onder de WIA; zonder verzekering of buffer kan het inkomen wegvallen."], ["Hij krijgt via de werkgever twee jaar loondoorbetaling", "Een zelfstandige heeft geen werkgever die loon doorbetaalt."], ["Hij is automatisch verzekerd via de NHG-borgtocht", "NHG is geen inkomensverzekering."], ["Zijn hypotheek wordt bij arbeidsongeschiktheid kwijtgescholden", "Arbeidsongeschiktheid leidt niet tot kwijtschelding van de hypotheek."]]],
["Waarvan hangt de duur van een WW-uitkering in hoofdlijnen af?", [["Van het arbeidsverleden van de werknemer", "Hoe langer iemand heeft gewerkt, hoe langer de WW-uitkering kan duren, tot een wettelijk maximum."], ["Van de hoogte van de hypotheek", "De hypotheek heeft geen invloed op de WW-duur."], ["Van de leeftijd van de partner", "De WW is een individuele werknemersverzekering, los van de partner."], ["Van de rentevaste periode van de lening", "De rentevaste periode speelt geen rol bij de WW."]]],
["Twee partners sluiten samen een hypotheek af en gaan na een paar jaar uit elkaar. Wat geldt tegenover de geldverstrekker?", [["Beide partners blijven hoofdelijk aansprakelijk voor de hele schuld tot de geldverstrekker één van hen ontslaat", "De geldverstrekker kan het volledige bedrag van ieder van hen vorderen; de onderlinge afspraken binden de bank niet."], ["Ieder is automatisch alleen aansprakelijk voor de helft van de schuld, naar rato van de eigendom", "Onderling kunnen zij de schuld verdelen, ook naar rato van de eigendom, maar tegenover de geldverstrekker zijn zij hoofdelijk aansprakelijk."], ["Alleen de partner die in de woning blijft, is nog aansprakelijk", "Vertrek uit de woning ontslaat iemand niet van de aansprakelijkheid."], ["De hypotheek vervalt bij een relatiebeëindiging en moet door de achterblijvende partner opnieuw worden afgesloten", "Een relatie-einde laat de bestaande kredietovereenkomst intact."]]],
["Een klant van 58 jaar sluit een hypotheek af met een looptijd tot na zijn AOW-leeftijd. Wat moet de adviseur in elk geval in kaart brengen?", [["Of de lasten na pensionering te dragen zijn met het verwachte AOW- en pensioeninkomen", "Na de AOW-leeftijd daalt het inkomen vaak; het advies moet laten zien of de woonlasten dan betaalbaar blijven."], ["Of de klant vóór zijn pensioen met de overwaarde nog een tweede woning kan kopen", "Een tweede woning is niet relevant voor de betaalbaarheid van deze hypotheek."], ["Of de rente na de AOW-leeftijd automatisch daalt", "Er is geen automatische renteverlaging bij pensionering."], ["Of de Wet Hillen de hypotheekrente na pensionering geheel of gedeeltelijk overneemt", "De Wet Hillen gaat over het eigenwoningforfait, niet over het overnemen van rente."]]],
["Hoe hoort de adviseur risico's zoals overlijden, arbeidsongeschiktheid en werkloosheid in het hypotheekadvies te behandelen?", [["De gevolgen doorrekenen, bespreken en de keuze van de klant vastleggen", "Een passend advies laat zien wat er gebeurt en welke oplossingen er zijn; de klant kiest bewust en dat wordt vastgelegd."], ["Alleen benoemen als de klant er zelf naar vraagt", "Een adviseur moet risico's uit zichzelf onderzoeken en bespreken."], ["Altijd voor elk risico een verzekering verplicht stellen", "Een verzekering is niet altijd nodig; een buffer of acceptatie kan ook passen."], ["Overlaten aan de geldverstrekker, omdat die de kredietwaardigheid toetst", "De kredietwaardigheidstoets vervangt de risicoanalyse van de adviseur niet."]]],
["Welke invloed heeft een gunstig energielabel van de woning op de leencapaciteit volgens de TRHK?", [["Afhankelijk van het label is extra leenruimte mogelijk", "De TRHK geeft extra leenruimte bij zuinigere woningen, omdat de energielasten daar lager zijn."], ["Een gunstig label verhoogt de maximale LTV naar 125%", "Het energielabel verhoogt de LTV niet tot zo'n niveau."], ["Het energielabel heeft geen invloed op de leennormen", "De TRHK houdt wel degelijk rekening met het energielabel."], ["Bij een gunstig label vervalt de toetsrente", "Het label raakt het leenbedrag, niet de toetsrentesystematiek."]]],
["Een klant wil energiebesparende voorzieningen, zoals zonnepanelen en isolatie, meefinancieren. Wat is volgens de leennormen mogelijk?", [["Onder voorwaarden een hypotheek boven 100% van de marktwaarde voor die voorzieningen", "Energiebesparende voorzieningen vormen een uitzondering op de hoofdregel van een LTV van maximaal 100%."], ["Alleen als de voorzieningen al vóór de aankoop zijn aangebracht en in de taxatie zijn meegenomen", "Ook nog aan te brengen voorzieningen kunnen worden meegefinancierd, vaak via een bouwdepot."], ["Nooit, omdat de LTV zonder uitzonderingen 100% is", "De TRHK kent juist voor energiebesparende voorzieningen een uitzondering."], ["Alleen via een persoonlijke lening buiten de hypotheek", "Meefinancieren binnen de hypotheek is juist mogelijk."]]],
["Hoe lang is een geregistreerd energielabel voor een woning geldig?", [["Tien jaar", "Een energielabel voor een woning heeft een geldigheidsduur van tien jaar."], ["Twee jaar", "Zo kort is de geldigheidsduur niet."], ["Vijf jaar", "De geldigheidsduur is langer dan vijf jaar."], ["Onbeperkt geldig", "Een energielabel heeft een beperkte geldigheidsduur."]]],
["Een klant financiert de verduurzaming via de hypotheek en het bedrag wordt in een bouwdepot gestort. Wat is de functie van dat bouwdepot?", [["Uitbetaling volgt pas op facturen voor de afgesproken maatregelen", "Het depot borgt dat het geld voor de voorzieningen wordt gebruikt die de waarde of de energiezuinigheid verbeteren."], ["Het geld wordt direct op de privérekening van de klant gestort", "Juist dat voorkomt het bouwdepot."], ["Het geld wordt belegd tot de rentevaste periode eindigt", "Een bouwdepot is geen beleggingsrekening."], ["Het geld dient als buffer voor betalingsachterstanden", "Een bouwdepot is bestemd voor de verbouwing, niet voor achterstanden."]]],
["Wat regelt de hypothekenrichtlijn (MCD) over koppelverkoop?", [["Koppelverkoop is in beginsel verboden; gebundelde verkoop (los verkrijgbaar) is toegestaan", "Bij koppelverkoop is het krediet niet los verkrijgbaar; dat is verboden. Een bundel waarbij de onderdelen ook los te krijgen zijn, mag wel."], ["Koppelverkoop is altijd toegestaan als de consument vooraf een ESIS met alle productcombinaties heeft gekregen", "Een ESIS maakt verboden koppelverkoop niet toelaatbaar."], ["Elke combinatie van een hypotheek met een ander product is verboden", "Gebundelde verkoop is wel toegestaan."], ["Koppelverkoop is alleen verboden bij hypotheken met NHG", "Het verbod volgt uit de richtlijn en geldt niet alleen bij NHG."]]],
["Waarop mag de kredietwaardigheidsbeoordeling volgens de hypothekenrichtlijn niet hoofdzakelijk worden gebaseerd?", [["Op de verwachting dat de woningwaarde zal stijgen", "De toets moet vooral kijken naar het vermogen van de consument om aan zijn verplichtingen te voldoen, niet op verwachte waardestijging."], ["Op het actuele inkomen van de consument uit loondienst of onderneming", "Het inkomen is juist een kernonderdeel van de beoordeling."], ["Op de vaste lasten en de bestaande verplichtingen van de consument", "Vaste lasten horen bij een goede beoordeling van de betaalcapaciteit."], ["Op de informatie uit het BKR-register", "BKR-informatie is een belangrijke bron en wordt juist gebruikt."]]],
["Wat is een hoofddoel van de hypothekenrichtlijn (MCD)?", [["Een hoog niveau van consumentenbescherming bij hypothecair krediet in de EU", "De MCD harmoniseert onder meer informatie, kredietwaardigheidstoets en vakbekwaamheid om consumenten te beschermen."], ["Het vaststellen van één Europese hypotheekrente voor alle lidstaten van de eurozone", "De MCD stelt geen rentes vast."], ["Het afschaffen van de renteaftrek in alle lidstaten", "Belastingregels zijn nationaal en vallen buiten de MCD."], ["Het vastleggen van één maximale LTV voor woninghypotheken in alle lidstaten", "De MCD schrijft geen LTV-maximum voor; dat is nationaal geregeld."]]],
["Mag een hypotheekadviseur een provisie ontvangen van de geldverstrekker voor de bemiddeling in een hypotheek voor een consument?", [["Nee, voor hypotheken geldt een provisieverbod", "Sinds 2013 mag een adviseur geen provisie van de aanbieder ontvangen voor hypotheken voor consumenten."], ["Ja, mits de provisie in het ESIS wordt vermeld", "Vermelding maakt de provisie niet toegestaan."], ["Ja, als de provisie lager is dan 1% van de hoofdsom", "Er geldt geen drempel; provisie is verboden."], ["Alleen als de klant schriftelijk toestemming geeft", "Toestemming van de klant heft het verbod niet op."]]],
["Een klant wil zo veel mogelijk lenen, ook al blijkt uit de inventarisatie dat de lasten zijn buffer volledig opmaken. Wat verwacht de zorgplicht van de adviseur?", [["Dat hij de risico's bespreekt, passend adviseert en alles vastlegt", "De adviseur moet het belang van de klant voorop stellen en hem wijzen op de gevolgen, ook als dat tegen zijn wens ingaat."], ["Dat hij de wens van de klant zonder commentaar uitvoert en het verschil laat tekenen", "Uitvoeren zonder kritische afweging past niet bij een adviesrelatie."], ["Dat hij de klant naar een andere adviseur verwijst", "Doorverwijzen is niet de verplichting; passend adviseren is dat wel."], ["Dat hij de AFM vooraf om toestemming vraagt", "De AFM geeft geen toestemming in individuele adviezen."]]],
["Waarom benaderen geldverstrekkers klanten met een aflossingsvrije hypotheek actief?", [["Om hen te wijzen op het risico van een onbetaalbare schuld aan het einde", "De AFM heeft aanbieders gevraagd klanten tijdig te wijzen op dit risico, passend bij hun zorgplicht."], ["Om de aflossingsvrije lening verplicht om te zetten in een annuïteitenlening", "Een verplichte omzetting is geen gevolg van deze benadering."], ["Om het overgangsrecht van de klant in te trekken", "Een geldverstrekker kan het fiscale overgangsrecht niet intrekken."], ["Om de woning opnieuw te laten taxeren voor de WOZ-waarde", "De WOZ-waarde wordt door de gemeente vastgesteld."]]],
["Een klant brengt voor de aankoop een groot bedrag eigen geld in waarvan de herkomst onduidelijk is. Wat vraagt de Wwft van de geldverstrekker?", [["De herkomst onderzoeken en zo nodig melden bij FIU-Nederland", "Het cliëntenonderzoek omvat de bron van de middelen; ongebruikelijke transacties moeten aan de FIU worden gemeld."], ["Het geld accepteren omdat het niet geleend is", "Ook eigen geld valt onder het cliëntenonderzoek."], ["De klant direct aangeven bij de politie", "Een Wwft-instelling meldt aan FIU-Nederland, niet rechtstreeks aan de politie."], ["De klant vragen een verklaring van herkomst bij de AFM of de Belastingdienst af te geven", "De AFM en de Belastingdienst geven geen verklaringen over de herkomst van geld af; het onderzoek ligt bij de Wwft-instelling zelf."]]],
["Een Wwft-instelling heeft een ongebruikelijke transactie van een klant gemeld. Mag zij de klant daarover informeren?", [["Nee, de instelling mag de klant niet vertellen dat een melding is gedaan", "De Wwft verbiedt het informeren van de klant over een melding, zodat het onderzoek niet wordt gefrustreerd."], ["Ja, de klant heeft op grond van de AVG altijd recht op inzage in de melding", "Het inzagerecht uit de AVG geldt hier niet; de geheimhoudingsplicht uit de Wwft gaat voor."], ["Ja, maar alleen schriftelijk en pas na afloop van de transactie aan de klant zelf", "Ook na afloop mag de klant niet over de melding worden ingelicht."], ["Alleen als de klant een hypotheek met NHG heeft", "NHG heeft geen enkele invloed op de geheimhoudingsplicht."]]],
["Twee partners kopen samen een woning die zij zelf gaan bewonen, ieder voor de helft. Partner A is 33 jaar, partner B is 37 jaar. De koopsom ligt onder de woningwaardegrens. Wat geldt voor de overdrachtsbelasting?", [["A is vrijgesteld voor zijn helft; B betaalt het verlaagde tarief", "De startersvrijstelling wordt per verkrijger beoordeeld; B voldoet niet aan de leeftijdseis."], ["Beiden zijn vrijgesteld omdat één van hen jonger is dan 35", "De vrijstelling geldt per persoon, niet per huishouden."], ["Beiden betalen het verlaagde tarief, omdat B te oud is", "A verliest zijn vrijstelling niet doordat B er niet aan voldoet."], ["Beiden betalen het algemene tarief omdat zij samen kopen", "Samen kopen is geen reden voor het algemene tarief; zij gaan de woning zelf bewonen."]]],
["Een starter van 28 jaar koopt een woning waarvan de koopsom iets boven de woningwaardegrens voor de startersvrijstelling ligt. Wat is het gevolg?", [["Hij heeft geen recht op de vrijstelling en betaalt over de hele koopsom het verlaagde tarief", "Boven de grens vervalt de vrijstelling volledig; zij geldt niet voor het deel tot de grens."], ["Hij betaalt alleen overdrachtsbelasting over het deel van de koopsom dat boven de woningwaardegrens ligt", "Er is geen gedeeltelijke vrijstelling; de grens werkt als een harde drempel."], ["Hij betaalt het algemene tarief over de hele koopsom", "Voor een woning die hij zelf bewoont, geldt het verlaagde tarief."], ["Hij kan de vrijstelling behouden door de woning binnen een jaar na aankoop te verbouwen", "Een latere verbouwing verandert de koopsom en de toets niet."]]],
["Hoe vaak kan iemand gebruikmaken van de startersvrijstelling in de overdrachtsbelasting?", [["Eenmaal", "De startersvrijstelling kan iedere koper maar één keer in zijn leven benutten."], ["Eenmaal per tien jaar", "Er is geen herhaling na een periode; het is eenmalig."], ["Zo vaak als hij een woning koopt onder de grens", "De vrijstelling is uitdrukkelijk bedoeld voor de eerste aankoop en eenmalig."], ["Tweemaal, eenmaal alleen en eenmaal met een partner", "Ook samen kopen geeft geen tweede kans voor dezelfde persoon."]]],
["Twee partners vragen samen een hypotheek aan. Hoe telt het inkomen van de minstverdienende partner sinds 2024 mee in het toetsinkomen?", [["Volledig, net als het hoogste inkomen", "Sinds 2024 telt het tweede inkomen voor 100% mee; de eerdere gedeeltelijke weging is afgebouwd."], ["Voor de helft, om het risico van uitval van dat inkomen te dekken", "Een weging van 50% is nooit de norm geweest en geldt nu zeker niet meer; het tweede inkomen telt volledig mee."], ["Niet, alleen het hoogste inkomen bepaalt de maximale hypotheek", "Het tweede inkomen telt wel mee; vroeger gedeeltelijk, sinds 2024 volledig."], ["Alleen als beide partners een vast contract voor onbepaalde tijd hebben", "Het soort contract bepaalt of een inkomen meetelt, maar de TRHK kent geen aparte eis van een vast contract voor het tweede inkomen."]]],
["Welke last maakt deel uit van de financieringslast zoals de TRHK die berekent?", [["De aflossing op de hypotheek", "De financieringslast bestaat uit rente en aflossing (en eventuele erfpachtcanon) op het hypothecair krediet."], ["De maandelijkse bijdrage aan de Vereniging van Eigenaars", "VvE-bijdragen zijn woonkosten, maar worden niet als financieringslast in de toets meegenomen."], ["De premie van de opstalverzekering van de woning", "De opstalpremie hoort bij de woonkosten maar is geen rente of aflossing op het krediet."], ["De gemeentelijke onroerendezaakbelasting voor eigenaren", "De OZB is een belasting op het bezit van de woning en telt niet als financieringslast."]]],
["Hoe verhoudt het financieringslastpercentage in de TRHK zich in het algemeen tot de hoogte van het toetsinkomen?", [["Bij een hoger inkomen is het percentage hoger", "Wie meer verdient, houdt na de vaste basisuitgaven relatief meer over en kan dus een groter deel van zijn inkomen aan woonlasten besteden."], ["Het percentage is voor alle inkomens gelijk, alleen de rente maakt verschil", "De tabellen variëren juist met het inkomen; een vast percentage voor iedereen zou lagere inkomens te zwaar belasten."], ["Bij een hoger inkomen is het percentage lager, omdat de belastingdruk stijgt", "Het percentage loopt met het inkomen op; de hogere belastingdruk is al verwerkt en draait dat niet om."], ["Het percentage hangt alleen af van de leeftijd van de aanvrager", "Leeftijd speelt alleen een rol rond de AOW-leeftijd; de hoogte van het inkomen en de toetsrente bepalen het percentage."]]],
["Een klant heeft een toetsinkomen van € 60.000. Bij zijn inkomen en toetsrente geldt een financieringslastpercentage van 25%. Wat is de maximale bruto maandlast voor rente en aflossing?", [["€ 1.250", "25% van € 60.000 is € 15.000 per jaar; gedeeld door 12 is dat € 1.250 per maand."], ["€ 1.500", "Dit is 30% van het inkomen per maand; het opgegeven percentage is 25%."], ["€ 15.000", "Dit is de maximale jaarlast; de vraag gaat over de maandlast, dus nog delen door 12."], ["€ 937,50", "Dit bedrag ontstaat door met netto in plaats van bruto lasten te rekenen; de TRHK rekent met de bruto last zonder correctie."]]],
["Wat moet een kredietgever doen als uit de kredietwaardigheidsbeoordeling blijkt dat de gevraagde hypotheek niet verantwoord is?", [["Het krediet in die vorm niet verstrekken", "De Wft verbiedt overkreditering: blijkt het krediet onverantwoord, dan mag de kredietgever het niet aangaan."], ["Het krediet verstrekken als de klant een verklaring tekent dat hij het risico aanvaardt", "Een afstandsverklaring van de klant heft het verbod op overkreditering niet op; de verantwoordelijkheid ligt bij de kredietgever."], ["Het krediet verstrekken tegen een hogere rente als compensatie voor het risico", "Een hogere rente maakt een onverantwoorde lening alleen maar zwaarder en is geen oplossing voor overkreditering."], ["Het krediet verstrekken, maar dit binnen een maand melden aan de AFM", "Er bestaat geen meldroute die overkreditering toelaatbaar maakt; het krediet mag dan niet worden verstrekt."]]],
["Een klant heeft een privéleaseauto. Hoe gaat de kredietgever daar bij de hypotheekaanvraag in beginsel mee om?", [["De leasetermijn telt mee als vaste last", "Private lease wordt bij het BKR geregistreerd en de maandtermijn wordt als vaste last meegewogen."], ["Private lease is een huurcontract en blijft daarom buiten beschouwing", "Hoewel juridisch een vorm van huur, wordt private lease wel geregistreerd en als verplichting meegenomen."], ["Alleen de restwaarde van de auto aan het einde van het contract telt mee", "Bij private lease is er geen restwaarde voor de klant; het gaat om de lopende maandtermijn."], ["De leaseauto verhoogt de leencapaciteit, omdat hij als bezitting geldt", "De klant is geen eigenaar van de auto; het contract levert een last op, geen vermogen."]]],
["Een klant koopt een nieuwbouwwoning van een projectontwikkelaar. Waarop wordt de woningwaarde voor de LTV-toets bij nieuwbouw doorgaans gebaseerd?", [["Op de koop-/aanneemsom inclusief meerwerk", "Bij nieuwbouw dient de vrij-op-naamprijs met het meerwerk als waarde; een taxatie is dan meestal niet nodig."], ["Op de WOZ-waarde die de gemeente na oplevering vaststelt", "De WOZ-waarde is er bij aankoop nog niet en wordt voor de LTV-toets niet gebruikt."], ["Op de grondwaarde, omdat de opstal nog gebouwd moet worden", "De financiering ziet op de complete woning; alleen de grondwaarde zou de waarde sterk onderschatten."], ["Op een gemiddelde van vergelijkbare bestaande woningen in de buurt", "Zo'n gemiddelde is geen toetsmaatstaf; bij nieuwbouw is de koop-/aanneemsom met meerwerk het uitgangspunt."]]],
["Wat hoort een geldverstrekker richting de klant te doen rond het einde van een rentevaste periode?", [["De klant tijdig vooraf informeren over de renteherziening en het nieuwe aanbod", "Zo kan de klant op tijd kiezen voor een nieuwe periode of vergelijken met andere aanbieders."], ["De rente automatisch voor dezelfde periode verlengen zonder de klant te informeren", "Stilzwijgend verlengen zonder informatie zou de keuzevrijheid van de klant ondermijnen; van de geldverstrekker wordt juist tijdige informatie verwacht."], ["De klant verplicht een nieuw hypotheekadvies laten volgen bij een erkend adviseur", "Een renteherziening vereist geen nieuw adviestraject; de klant mag zelf kiezen."], ["De lening volledig opeisen als de klant niet binnen een week reageert", "Het aflopen van de rentevaste periode is geen opeisingsgrond; de lening loopt gewoon door."]]],
["Een klant ontvangt van zijn geldverstrekker een bindend hypotheekaanbod. Wat geldt volgens de regels voor hypothecair krediet aan consumenten?", [["Het aanbod blijft minstens veertien dagen geldig", "Deze bedenktijd uit de hypothekenrichtlijn geeft de consument tijd om het aanbod te beoordelen voordat hij gebonden is."], ["De klant moet het aanbod binnen drie dagen accepteren, anders vervalt het", "Drie dagen is de bedenktijd bij de koopakte van een woning, niet de geldigheid van een hypotheekaanbod."], ["De geldverstrekker mag het aanbod op elk moment intrekken als de rente stijgt", "Tijdens de bedenktijd kan de kredietgever het aanbod niet eenzijdig intrekken vanwege een rentestijging."], ["Een bindend aanbod is pas geldig nadat de notaris de akte heeft gepasseerd", "Het aanbod gaat vooraf aan de akte; de notaris passeert de akte juist op basis van het geaccepteerde aanbod."]]],
["Een klant leent € 200.000 annuïtair in 30 jaar tegen 4% rente. De bruto maandlast is ongeveer € 954,83. Hoeveel lost hij in de eerste maand af?", [["Ongeveer € 288,16", "De rente in maand 1 is € 200.000 × 4% / 12 = € 666,67; de rest van de annuïteit, € 288,16, is aflossing."], ["Ongeveer € 555,56", "Dit is de aflossing bij een lineaire lening (€ 200.000 / 360); bij een annuïteit is de aflossing in het begin lager."], ["Ongeveer € 666,67", "Dit is het rentedeel van de eerste maand, niet het aflossingsdeel."], ["Ongeveer € 954,83", "Dit is de volledige bruto maandlast; daarvan is het grootste deel nog rente."]]],
["Een klant heeft een lineaire hypotheek van € 360.000 met een looptijd van 30 jaar en een rente van 4,2%. Met hoeveel daalt de bruto maandlast elke maand?", [["€ 3,50", "Hij lost elke maand € 1.000 af (€ 360.000 / 360); de rente daarover is € 1.000 × 4,2% / 12 = € 3,50 minder per maand."], ["€ 1.000,00", "Dit is het vaste maandelijkse aflossingsbedrag, niet de daling van de maandlast."], ["€ 42,00", "Dit is de jaarrente over € 1.000; per maand daalt de rente met een twaalfde daarvan."], ["€ 0,00, de bruto maandlast blijft gelijk zolang de rente vaststaat", "Gelijkblijvende bruto lasten horen bij een annuïteit; bij lineair dalen de lasten doordat de schuld afneemt."]]],
["Wat is kenmerkend voor een traditionele spaarhypotheek gekoppeld aan een spaarverzekering?", [["De rente op het spaardeel is gelijk aan de hypotheekrente", "Doordat spaardeel en lening hetzelfde rendement hebben, werkt de constructie netto vergelijkbaar met een annuïteit."], ["Het spaardeel wordt belegd in aandelen met een wisselend rendement", "Beleggen in aandelen is kenmerkend voor de beleggingshypotheek, niet voor de spaarhypotheek."], ["De klant lost maandelijks rechtstreeks af op de lening", "Bij een spaarhypotheek blijft de lening staan en wordt via het spaardeel aan het einde in één keer afgelost."], ["De rente op het spaardeel staat altijd vast voor de hele looptijd", "De spaarrente volgt de hypotheekrente en kan dus bij een renteherziening wijzigen."]]],
["Wat is kenmerkend voor een krediethypotheek (hypothecair doorlopend krediet)?", [["De klant kan tot een limiet geld opnemen en weer terugstorten", "Een krediethypotheek werkt als een doorlopend krediet met de woning als zekerheid; de rente is vaak variabel."], ["De klant ontvangt het hele bedrag ineens en lost in vaste termijnen af", "Dat beschrijft een gewone annuïtaire of lineaire lening, niet een doorlopende kredietfaciliteit."], ["De rente wordt nooit in rekening gebracht zolang de klant niets opneemt", "Over het niet-opgenomen deel betaalt de klant geen rente, maar dat is een gevolg en niet wat de vorm kenmerkt."], ["De lening wordt automatisch afgelost uit een gekoppelde levensverzekering", "Koppeling aan een verzekering is kenmerkend voor een levenhypotheek, niet voor een krediethypotheek."]]],
["Een oudere klant overweegt een verzilverhypotheek waarbij hij geen maandlasten betaalt en de rente wordt bijgeschreven. Welk risico hoort de adviseur vooral te bespreken?", [["De schuld groeit door renteopbouw en kan de overwaarde opeten", "Doordat rente op rente wordt bijgeschreven, neemt de schuld steeds toe en blijft er minder over voor de klant of de erfgenamen."], ["De maandlasten kunnen bij een rentestijging fors en direct toenemen", "Er zijn geen maandlasten; een rentestijging laat vooral de schuld sneller groeien."], ["De klant moet de lening na tien jaar in één keer aflossen", "Een verzilverhypotheek wordt doorgaans pas bij verkoop of overlijden afgelost, niet na een vaste termijn."], ["De woning komt direct in eigendom van de geldverstrekker", "De klant blijft eigenaar; de geldverstrekker heeft alleen een hypotheekrecht als zekerheid."]]],
["Een klant koopt een nieuwe woning en wil zijn huidige hypotheekrente meenemen. Welke productvoorwaarde maakt dat mogelijk?", [["Een meeneemregeling (verhuisregeling)", "Hiermee neemt de klant de bestaande rente en rentevaste periode mee naar de financiering van de nieuwe woning."], ["Een rentedaalgarantie in de offerte voor de nieuwe woning", "Een rentedaalgarantie zorgt dat een lagere rente vóór passeren wordt toegepast, niet dat de oude rente wordt meegenomen."], ["Een overbruggingskrediet op de oude woning", "Een overbrugging maakt overwaarde tijdelijk beschikbaar, maar regelt niets over de rente."], ["Een plafondrente op het nieuwe leningdeel", "Een plafondrente begrenst een variabele rente en heeft niets met verhuizen te maken."]]],
["Wat is een starterslening, zoals gemeenten die via SVn kunnen aanbieden?", [["Een aanvullende lening naast de hypotheek", "De starterslening komt boven op de reguliere hypotheek en heeft vaak gunstige voorwaarden in de eerste jaren."], ["Een subsidie die de starter niet hoeft terug te betalen", "Het is een lening die wel moet worden terugbetaald, ook al zijn de eerste jaren vaak rente- en aflossingsvrij."], ["Een hypotheek die de verplichting tot NHG vervangt", "Een starterslening is aanvullend en vervangt NHG niet; vaak worden ze juist samen gebruikt."], ["Een vrijstelling van overdrachtsbelasting voor jonge kopers", "De startersvrijstelling is een belastingregel; de starterslening is een financieringsproduct."]]],
["Een klant heeft een aflossingsvrij leningdeel uit 2010 en wil dat omzetten in een annuïtaire lening. Wat is fiscaal juist?", [["Het blijft eigenwoningschuld met renteaftrek", "Aflossen mag altijd; het overgangsrecht beschermt de aftrek bij aflossingsvrij, maar sneller aflossen is geen probleem."], ["De lening valt na omzetting voortaan in box 3", "Omzetten naar een aflossende vorm verandert de status van eigenwoningschuld niet."], ["De klant krijgt een nieuwe dertigjaarstermijn vanaf de datum van omzetting", "De oorspronkelijke 30-jaarstermijn loopt gewoon door; omzetting geeft geen nieuwe termijn."], ["De omzetting is alleen mogelijk met toestemming van de Belastingdienst", "Voor het omzetten van de aflossingsvorm is geen toestemming van de Belastingdienst nodig."]]],
["Wanneer is een woning fiscaal een eigen woning in de zin van de Wet IB 2001?", [["Als zij hem als hoofdverblijf ter beschikking staat", "Het hoofdverblijfcriterium is de kern van de eigenwoningregeling (meestal krachtens eigendom); een tweede woning of beleggingspand valt erbuiten."], ["Als de klant er ingeschreven staat, ook als hij er feitelijk niet woont", "De inschrijving in de BRP is een aanwijzing, maar het feitelijke hoofdverblijf is beslissend."], ["Als de woning met een hypotheek is gefinancierd, ongeacht wie erin woont", "Financiering met een hypotheek maakt een woning nog geen eigen woning; het gaat om het hoofdverblijf."], ["Als de klant er minstens drie maanden per jaar verblijft", "Een minimumaantal maanden is niet het criterium; het moet het hoofdverblijf zijn."]]],
["Een klant heeft sinds 1995 een hypotheek op zijn eigen woning. Vanaf welk moment loopt de 30-jaarstermijn voor renteaftrek over deze schuld?", [["Vanaf 1 januari 2001", "Voor schulden van vóór de Wet IB 2001 is de termijn op 1 januari 2001 gaan lopen; de aftrek eindigt dus uiterlijk eind 2030."], ["Vanaf de datum van het afsluiten in 1995", "De termijn van 30 jaar bestond in 1995 nog niet; voor bestaande schulden is gestart op 1 januari 2001."], ["Vanaf 1 januari 2013", "In 2013 ging de aflossingseis in, maar de 30-jaarstermijn voor oude schulden liep al sinds 2001."], ["Er geldt geen termijn, oude schulden hebben onbeperkte aftrek", "Ook schulden van vóór 2001 vallen onder de maximale aftrekduur van 30 jaar."]]],
["Een klant koopt een woning. Welke notariskosten zijn als financieringskosten direct aftrekbaar in box 1?", [["De notariskosten voor de hypotheekakte", "Kosten van de hypotheekakte zijn kosten van het afsluiten van de lening en daarom aftrekbaar."], ["De notariskosten voor de leveringsakte", "De leveringsakte hoort bij de verwerving van de woning; die kosten zijn niet aftrekbaar, wel financierbaar."], ["De overdrachtsbelasting die de notaris namens de staat int", "Overdrachtsbelasting hoort bij de verwervingskosten en is niet aftrekbaar."], ["Het kadastrale inschrijvingsrecht voor de eigendomsoverdracht", "Kosten voor de inschrijving van de levering zijn verwervingskosten en niet direct aftrekbaar."]]],
["Een klant financiert de kosten koper, zoals overdrachtsbelasting en leveringskosten, mee in de hypotheek. Wat is fiscaal juist?", [["Dat leningdeel kan eigenwoningschuld zijn", "Verwervingskosten tellen mee voor de eigenwoningschuld; de rente erover is aftrekbaar als aan de overige eisen is voldaan."], ["De kosten zelf zijn direct aftrekbaar en het leningdeel valt in box 3", "Het is net andersom: de kosten zijn niet aftrekbaar, maar het leningdeel kan wel eigenwoningschuld zijn."], ["Kosten koper mogen nooit worden geleend, ook niet buiten de TRHK", "Fiscaal kan het; de LTV-norm beperkt wel hoeveel er boven de marktwaarde mag worden geleend."], ["Het leningdeel is alleen aftrekbaar als het aflossingsvrij is", "Een aflossingsvrije lening na 2012 voldoet juist niet aan de aflossingseis en geeft geen aftrek."]]],
["Tegen welk tarief is de hypotheekrente op een eigenwoningschuld voor een klant met een hoog inkomen maximaal aftrekbaar?", [["Tegen het tarief van de eerste schijf (basistarief)", "De aftrek is afgebouwd tot het basistarief; ook bij een inkomen in de hoogste schijf levert de aftrek niet meer op."], ["Tegen het toptarief, omdat het inkomen in de hoogste schijf valt", "Aftrek tegen het toptarief is afgebouwd; het voordeel is beperkt tot het basistarief."], ["Tegen het box 3-tarief", "De eigen woning valt in box 1; het box 3-tarief speelt bij de renteaftrek geen rol."], ["Tegen een vast percentage van de WOZ-waarde", "Een percentage van de WOZ-waarde is het eigenwoningforfait, geen aftrektarief."]]],
["Wat geldt voor een eigen woning met een WOZ-waarde boven de grens waarboven het hogere forfait (de 'villataks') geldt?", [["Een hoger forfaitpercentage over het meerdere", "Het eigenwoningforfait is voor dure woningen verhoogd over het meerdere boven de grens, om de aftrek per saldo te beperken."], ["Over de hele WOZ-waarde vervalt het eigenwoningforfait", "Het forfait vervalt niet; het wordt boven de grens juist hoger."], ["De hypotheekrente is boven die grens niet meer aftrekbaar", "De renteaftrek blijft gewoon bestaan; alleen het forfait wordt boven de grens verhoogd."], ["De woning valt boven die grens geheel in box 3", "Ook een dure woning blijft een eigen woning in box 1 als zij het hoofdverblijf is."]]],
["Een gehuwde klant verlaat na een scheiding de woning; zijn ex-echtgenote blijft er wonen. Hoe lang kan hij de woning fiscaal nog als eigen woning behandelen?", [["Maximaal twee jaar, zolang zijn ex er blijft wonen", "Voor de vertrekkende partner blijft de woning tijdelijk eigen woning, mits de (gewezen) partner haar als hoofdverblijf bewoont."], ["Tot de echtscheiding in de registers is ingeschreven, daarna direct box 3", "De wet geeft een vaste termijn vanaf het vertrek, los van het moment van inschrijving van de scheiding."], ["Zolang hij eigenaar blijft, ook als de woning wordt verhuurd", "Bij verhuur aan derden is er geen eigen woning meer; de regeling vereist bewoning door de (ex-)partner."], ["Drie jaar, net als bij een leegstaande woning die te koop staat", "Drie jaar geldt voor een leegstaande woning in de verkoop; bij scheiding is de termijn twee jaar."]]],
["Een klant wil een schenking van zijn ouders gebruiken om op zijn eigenwoningschuld af te lossen. Wat geldt sinds 1 januari 2024 voor de schenkvrijstelling eigen woning?", [["Die is afgeschaft", "De verhoogde vrijstelling voor de eigen woning (de 'jubelton') bestaat sinds 2024 niet meer."], ["Die is verhoogd voor kinderen jonger dan 40 jaar", "De vrijstelling is niet verhoogd maar volledig afgeschaft."], ["Die geldt alleen nog voor aflossing en niet meer voor aankoop", "De vrijstelling is voor alle eigenwoningbestedingen vervallen, ook voor aflossing."], ["Die mag sinds 2024 over drie jaren worden gespreid", "Spreiding was een kenmerk van de oude regeling; sinds 2024 bestaat de hele vrijstelling niet meer."]]],
["Een klant wil zijn woning met NHG financieren maar is van plan haar direct te verhuren. Wat is juist?", [["NHG is niet mogelijk; eigen bewoning is vereist", "NHG is bedoeld voor de financiering van een woning die de klant als hoofdverblijf gaat bewonen."], ["NHG is mogelijk als de huurinkomsten de maandlasten dekken", "Ook dekkende huurinkomsten maken een verhuurde woning niet geschikt voor NHG; de voorwaarde is eigen bewoning."], ["NHG is mogelijk, maar tegen een dubbele borgtochtprovisie", "Een hogere provisie voor verhuur bestaat niet; verhuurde woningen vallen buiten de regeling."], ["NHG is mogelijk als de huurder ook een NHG-verklaring tekent", "De huurder is geen partij bij de lening; eigen bewoning door de klant blijft vereist."]]],
["Waar staan de voorwaarden waaraan een NHG-lening moet voldoen?", [["In de Voorwaarden & Normen van de Stichting WEW", "De Stichting WEW stelt deze voorwaarden vast en past ze periodiek aan, onder meer de kostengrens."], ["In de Gedragscode Hypothecaire Financieringen", "De GHF bevat minimumeisen voor offertes en voorwaarden, niet de NHG-normen."], ["In de Wet inkomstenbelasting 2001", "De Wet IB regelt de fiscale behandeling, niet de voorwaarden voor de borgtocht."], ["In het Besluit Gedragstoezicht financiële ondernemingen", "Dat besluit bevat Wft-gedragsregels; de NHG-voorwaarden zijn privaatrechtelijk vastgesteld door de stichting."]]],
["Een klant wil met NHG ook energiebesparende maatregelen meefinancieren. Wat geldt voor de NHG-kostengrens?", [["Die mag voor energiebesparende voorzieningen worden verhoogd", "De Voorwaarden & Normen bieden extra ruimte boven de gewone kostengrens voor energiebesparende maatregelen."], ["Die geldt dan niet meer, het hele bedrag valt onder NHG", "Er blijft een maximum gelden; de extra ruimte voor verduurzaming is begrensd."], ["Die wordt lager, omdat duurzame woningen minder risico lopen", "Verduurzaming leidt niet tot een lagere grens; de regeling stimuleert juist extra ruimte."], ["Verduurzaming kan nooit met NHG worden gefinancierd", "Verduurzaming kan juist onder voorwaarden met NHG worden meegefinancierd."]]],
["In welk register moet een taxateur die een woning taxeert voor een hypothecaire financiering in Nederland zijn ingeschreven?", [["In het Nederlands Register Vastgoed Taxateurs (NRVT)", "Geldverstrekkers en validatie-instituten accepteren voor hypotheken alleen rapporten van in het NRVT ingeschreven taxateurs."], ["In het register van financiële dienstverleners van de AFM", "Het AFM-register is voor financiële dienstverleners; taxateurs staan in het NRVT."], ["In het Kadaster", "Het Kadaster registreert onroerende zaken en rechten, geen taxateurs."], ["In het register van Kifid", "Kifid behandelt klachten over financiële diensten en houdt geen register van taxateurs bij."]]],
["Wat is een modelmatige waardering van een woning?", [["Een geautomatiseerde waardebepaling op basis van marktdata", "Sommige geldverstrekkers accepteren deze waardering onder voorwaarden, bijvoorbeeld bij een lage LTV."], ["Een taxatie die de taxateur uitvoert met een maquette van de woning", "Een maquette speelt geen rol; het gaat om een rekenmodel met marktdata."], ["De waardering van een modelwoning in een nieuwbouwproject", "Een modelwoning is een voorbeeldwoning; modelmatig waarderen is iets anders."], ["Een bouwkundige keuring volgens een vast model van de NHG", "Een bouwkundige keuring beoordeelt de staat, niet de marktwaarde."]]],
["Waarom gebruikt een geldverstrekker voor een nieuwe financiering in de regel niet de WOZ-waarde als basis voor de LTV?", [["Omdat zij voor belastingheffing dient en achterloopt", "De WOZ-waarde loopt achter op de markt en is niet bedoeld als actuele marktwaarde voor een financiering."], ["Omdat de WOZ-waarde altijd hoger is dan de marktwaarde", "De WOZ-waarde kan lager of hoger uitvallen; het probleem is dat zij niet actueel en niet voor financiering bedoeld is."], ["Omdat de AFM het gebruik van de WOZ-waarde verbiedt bij alle hypotheken", "Er is geen algemeen verbod; sommige geldverstrekkers gebruiken de WOZ-waarde wel bij beperkte verhogingen."], ["Omdat de WOZ-waarde alleen voor huurwoningen wordt vastgesteld", "De gemeente stelt voor alle woningen een WOZ-waarde vast, ook voor koopwoningen."]]],
["Waarom is de executiewaarde als maatstaf voor de maximale hypotheek vervangen door de marktwaarde?", [["Omdat de marktwaarde objectiever is vast te stellen", "De executiewaarde was een schatting van een veilingopbrengst; de TRHK baseert de LTV-norm op de marktwaarde."], ["Omdat executie van woningen sinds 2013 niet meer is toegestaan", "Executie is nog steeds mogelijk; alleen de rekenmaatstaf is veranderd."], ["Omdat de executiewaarde altijd hoger lag dan de marktwaarde", "De executiewaarde lag juist lager dan de marktwaarde."], ["Omdat de notaris de executiewaarde niet meer in de akte mag opnemen", "De keuze voor de marktwaarde komt uit de leennormen, niet uit regels voor de akte."]]],
["Wanneer gaat de eigendom van een woning bij aankoop juridisch over op de koper?", [["Bij inschrijving van de leveringsakte in het Kadaster", "Voor de overdracht van een onroerende zaak is een notariële akte en inschrijving in het Kadaster vereist."], ["Bij ondertekening van de koopovereenkomst bij de makelaar", "De koopovereenkomst verplicht tot levering, maar draagt de eigendom nog niet over."], ["Bij betaling van de waarborgsom of bankgarantie", "De waarborgsom is zekerheid voor de verkoper; de eigendom gaat pas over bij levering."], ["Bij afgifte van de sleutels door de verkoper", "Het overhandigen van de sleutels is feitelijke levering, geen juridische eigendomsoverdracht."]]],
["Een particuliere koper tekent op maandag de koopakte voor een woning en ontvangt die dezelfde dag. Wat geldt?", [["Hij heeft drie dagen bedenktijd", "Het BW geeft een consument-koper van een woning drie dagen bedenktijd na terhandstelling van de koopakte."], ["Hij heeft veertien dagen bedenktijd, zoals bij koop op afstand", "Veertien dagen geldt bij koop op afstand; bij woningkoop is de bedenktijd drie dagen."], ["Hij kan alleen ontbinden als de financiering niet rond komt", "Een financieringsvoorbehoud is een aparte ontbindende voorwaarde; de bedenktijd staat daar los van."], ["Hij heeft geen bedenktijd, omdat hij persoonlijk heeft getekend", "Ook bij persoonlijk tekenen heeft een particuliere koper wettelijke bedenktijd."]]],
["Wat is een wettelijk vereiste voor de koop van een woning door een consument?", [["De koopovereenkomst moet schriftelijk worden aangegaan", "Bij koop van een woning door een consument is de koop pas tot stand gekomen als deze schriftelijk is vastgelegd."], ["De koopovereenkomst moet door een notaris worden opgesteld", "De koopakte wordt vaak door een makelaar opgesteld; alleen de leveringsakte is notarieel."], ["De koopprijs moet zijn goedgekeurd door de taxateur", "Een taxatie is geen voorwaarde voor een geldige koopovereenkomst."], ["De koper moet bij ondertekening een hypotheekofferte overleggen", "Een offerte is geen voorwaarde voor de koop; daarvoor dient eventueel een financieringsvoorbehoud."]]],
["Een koper heeft in de koopakte een financieringsvoorbehoud tot een bepaalde datum. Vóór die datum wijst de geldverstrekker zijn aanvraag af. Wat kan hij doen?", [["De koop tijdig ontbinden met een beroep op het voorbehoud", "Het voorbehoud is een ontbindende voorwaarde; mits tijdig en volgens de akte ingeroepen, kan hij zonder boete ontbinden."], ["Niets, de koop staat vast zodra de bedenktijd voorbij is", "Na de bedenktijd kan de koper zich nog op een overeengekomen voorbehoud beroepen."], ["Ontbinden, maar alleen tegen betaling van de afgesproken boete", "Bij een terecht beroep op het voorbehoud is er juist geen boete verschuldigd."], ["De koop automatisch laten vervallen zonder iets aan de verkoper te melden", "Het voorbehoud werkt niet stilzwijgend; de koper moet zich tijdig en zoals afgesproken op ontbinding beroepen."]]],
["Wat is het doel van de bankgarantie of waarborgsom die een koper na het tekenen van de koopakte stelt?", [["Zekerheid voor de verkoper bij wanprestatie van de koper", "Komt de koper niet na, dan kan de verkoper een boete verhalen op de waarborgsom of bankgarantie."], ["Een eerste aflossing op de nieuwe hypotheek", "De waarborgsom is geen aflossing; zij wordt bij de levering verrekend met de koopsom."], ["Betaling van de makelaarscourtage die de verkoper verschuldigd is", "De courtage is een afspraak tussen verkoper en makelaar en staat los van de waarborgsom."], ["Een borg voor de NHG-borgtochtprovisie", "De NHG-provisie wordt bij de financiering betaald en heeft niets met de waarborgsom te maken."]]],
["Waarvoor gebruikt de notaris bij een woningtransactie een derdengeldenrekening?", [["Om de gelden van alle partijen veilig af te wikkelen", "Het geld staat afgescheiden van het vermogen van de notaris en wordt pas na inschrijving van de akten uitbetaald."], ["Om de notariskosten vooraf te innen bij de koper", "De rekening is niet bedoeld voor eigen kosten van de notaris maar voor gelden van derden."], ["Om de overdrachtsbelasting een jaar te laten renderen", "De notaris draagt overdrachtsbelasting af en mag geld van derden niet voor eigen rendement gebruiken."], ["Om de lening tijdens de looptijd te beheren voor de geldverstrekker", "Na de afwikkeling heeft de notaris geen rol meer in het beheer van de lening."]]],
["Hoe worden de partijen bij een hypotheekrecht juridisch genoemd?", [["De geldnemer is hypotheekgever, de geldverstrekker hypotheekhouder", "De consument geeft de woning als zekerheid (hypotheekgever); de bank verkrijgt het recht (hypotheekhouder of hypotheeknemer)."], ["De geldverstrekker is hypotheekgever, de geldnemer hypotheekhouder", "Dat is precies omgekeerd: wie het geld leent, verleent het hypotheekrecht."], ["De notaris is hypotheekhouder namens beide partijen", "De notaris stelt de akte op, maar is zelf geen partij bij het hypotheekrecht."], ["De taxateur is hypotheekhouder tot de woning is getaxeerd", "De taxateur bepaalt de waarde en verkrijgt geen enkel zekerheidsrecht."]]],
["Wat betekent het dat een hypotheekrecht een afhankelijk (accessoir) recht is?", [["Het bestaat alleen zolang de vordering bestaat", "Een hypotheekrecht volgt de vordering; is de schuld voldaan (bij een gewone hypotheek), dan vervalt het recht."], ["Het is afhankelijk van toestemming van de gemeente", "Voor het vestigen van een hypotheekrecht is geen toestemming van de gemeente nodig."], ["Het kan alleen bestaan als er ook een NHG-borgtocht is", "Een hypotheekrecht bestaat ook zonder NHG; NHG is een aanvullende borgtocht."], ["Het vervalt automatisch als de woning wordt verkocht", "Het hypotheekrecht blijft bij verkoop op de woning rusten tot het is doorgehaald."]]],
["Een klant heeft zijn hypotheek volledig afgelost. Hoe verdwijnt de hypotheekinschrijving uit de openbare registers?", [["Door doorhaling (royement) in de registers", "Na aflossing moet het recht formeel worden doorgehaald in het Kadaster, anders blijft de inschrijving zichtbaar."], ["Automatisch, zodra de laatste termijn is betaald", "Het Kadaster weet niet dat de schuld is afgelost; de doorhaling moet worden aangevraagd."], ["Door een mededeling van de klant aan de gemeente", "De gemeente houdt de hypotheekregisters niet bij; dat doet het Kadaster."], ["Pas als de woning wordt verkocht aan een nieuwe eigenaar", "De doorhaling kan direct na aflossing; het is niet nodig te wachten op verkoop."]]],
["In een hypotheekakte staat een huurbeding. Wat betekent dit voor de hypotheekhouder?", [["Hij kan bij executie een huur zonder zijn toestemming negeren", "Het huurbeding beschermt de executiewaarde: een woning zonder huurder brengt meer op."], ["Hij mag de woning zelf verhuren zolang de klant geen achterstand heeft", "Het huurbeding geeft geen recht om de woning tijdens een normale looptijd te verhuren."], ["Hij ontvangt automatisch een deel van eventuele huurinkomsten", "Het beding regelt geen deling van huur, maar beperkt verhuur zonder toestemming."], ["De klant moet de woning verplicht verhuren als hij verhuist", "Er is geen verhuurplicht; het beding verbiedt juist verhuur zonder toestemming."]]],
["Een klant koopt een appartement. Waarop moet de adviseur in verband met de Vereniging van Eigenaars (VvE) onder meer letten?", [["De VvE-bijdrage en het reservefonds", "Hoge bijdragen of een te klein reservefonds kunnen de woonlasten en de verkoopbaarheid van het appartement sterk raken."], ["Of de VvE ook de hypotheekrente betaalt", "De VvE betaalt nooit de hypotheekrente van een eigenaar; zij beheert het gemeenschappelijke gebouw."], ["Of de VvE de leennormen goedkeurt", "Een VvE heeft geen rol bij de kredietwaardigheidstoets van een eigenaar."], ["Of de VvE toestemming geeft voor de hypotheekakte", "Voor het vestigen van een hypotheek op een appartementsrecht is geen VvE-toestemming nodig."]]],
["Een stel trouwt in 2026 zonder huwelijkse voorwaarden. De man kocht zijn woning al vóór het huwelijk op eigen naam. Wat geldt in beginsel?", [["De woning blijft privé van de man en valt niet in de gemeenschap", "Sinds 2018 geldt de beperkte gemeenschap: voorhuwelijks vermogen blijft privé."], ["De woning valt volledig in de gemeenschap van goederen", "Dat gold vóór 2018; sinds de Wet beperking gemeenschap valt voorhuwelijks bezit er niet meer in."], ["De woning wordt automatisch voor de helft op naam van de vrouw gezet", "Een huwelijk wijzigt de inschrijving in het Kadaster niet."], ["De hypotheek valt in de gemeenschap, de woning blijft privé", "Schulden die bij het privévermogen horen, blijven ook privé."]]],
["Twee ongehuwd samenwonenden kopen samen een woning. Hoe kunnen zij regelen dat de langstlevende het aandeel van de overledene verkrijgt?", [["Met een verblijvingsbeding in een notarieel samenlevingscontract", "Zo'n beding laat het aandeel van de overledene naar de langstlevende gaan; zonder regeling erven anderen."], ["Dat gaat automatisch, omdat zij samen op de hypotheekakte staan", "Gezamenlijk debiteurschap regelt niets over vererving van het eigendomsaandeel."], ["Door de woning bij de gemeente als gezamenlijk hoofdverblijf te melden", "Inschrijving op hetzelfde adres heeft geen erfrechtelijke gevolgen."], ["Door een overlijdensrisicoverzekering op naam van één partner te sluiten", "Een ORV geeft geld bij overlijden, maar regelt niet wie eigenaar wordt van de woning."]]],
["Wat houdt rentemiddeling in?", [["Oude rente en boete worden verwerkt in een nieuwe rente", "In plaats van de vergoeding ineens te betalen, gaat de klant een gemiddelde rente betalen voor een nieuwe periode."], ["De rente wordt elk jaar gemiddeld met de rente van andere klanten", "Rentemiddeling is een individuele afspraak bij tussentijds herzien, geen gemiddelde over klanten."], ["De klant betaalt de helft van de rente nu en de rest bij het einde van de looptijd", "Uitstel van rentebetaling is iets anders; bij rentemiddeling blijft de klant gewoon maandelijks rente betalen."], ["De rente wordt gemiddeld met de rente van de vorige geldverstrekker bij oversluiten", "Rentemiddeling gebeurt bij dezelfde geldverstrekker, niet bij oversluiten naar een andere."]]],
["Waardoor wordt de hoogte van een variabele hypotheekrente vooral beïnvloed?", [["Door de korte geldmarktrente, zoals de Euribor", "Variabele rentes bewegen mee met de korte rente waartegen banken geld lenen, aangevuld met opslagen voor kosten en risico."], ["Door de rente op tienjarige staatsleningen", "Lange rentes zijn bepalend voor lange rentevaste periodes, niet voor de variabele rente."], ["Door de stand van de AEX-index", "Aandelenkoersen bepalen de hypotheekrente niet rechtstreeks."], ["Door de jaarlijkse inflatiecorrectie van de NHG-kostengrens", "De NHG-kostengrens is een leengrens en geen rente-indicator."]]],
["Wat is het verschil tussen de looptijd en de rentevaste periode van een hypotheek?", [["De duur van de lening tegenover de duur van de vaste rente", "Bij een looptijd van 30 jaar kan de klant bijvoorbeeld meerdere rentevaste periodes van 10 jaar hebben."], ["Er is geen verschil, het zijn twee namen voor hetzelfde begrip", "Ze vallen alleen samen bij een rente die voor de hele looptijd vaststaat; meestal zijn ze verschillend."], ["De rentevaste periode is altijd langer dan de looptijd", "De rentevaste periode kan nooit langer zijn dan de looptijd van de lening."], ["De looptijd geldt alleen voor het aflossingsvrije deel", "Ook aflossingsvrije en aflossende delen hebben elk een looptijd en een rentevaste periode."]]],
["Bij een normale (oplopende) rentecurve: hoe verhoudt de rente bij een rentevaste periode van 20 jaar zich doorgaans tot die bij 5 jaar?", [["De rente voor 20 jaar is doorgaans hoger, als prijs voor langere zekerheid", "Bij een normale rentecurve is lang geld duurder; de klant betaalt voor zekerheid tegen rentestijging."], ["De rente voor 20 jaar is doorgaans lager, omdat de bank minder administratie heeft", "Administratiekosten bepalen de rente nauwelijks; bij een normale curve ligt lange rente juist hoger."], ["De rentes zijn altijd gelijk, de looptijd maakt niet uit", "Rentes verschillen per periode; daarom is de keuze voor de rentevaste periode zo belangrijk."], ["De rente voor 20 jaar is altijd precies het dubbele van die voor 5 jaar", "Er is geen vaste rekenregel; het verschil hangt af van de markt."]]],
["In welke situatie hoeft een klant volgens de meeste hypotheekvoorwaarden geen vergoeding voor vervroegde aflossing te betalen?", [["Bij verkoop en levering van de woning aan een derde", "Bij verkoop en verhuizing is aflossen boetevrij volgens de gangbare voorwaarden; dit sluit aan bij de GHF."], ["Bij oversluiten naar een andere geldverstrekker vanwege een lagere rente", "Oversluiten tijdens de rentevaste periode is juist de typische situatie waarin een vergoeding verschuldigd kan zijn."], ["Bij aflossing uit eigen spaargeld boven de boetevrije ruimte", "Boven de boetevrije ruimte kan een vergoeding verschuldigd zijn als de marktrente lager is."], ["Bij aflossing met geld uit een box 3-belegging tijdens de rentevaste periode", "De herkomst van het geld maakt niet uit; het gaat om het moment en het bedrag van aflossing."]]],
["Wat is de boetevrije aflossingsruimte bij een hypotheek?", [["Het bedrag dat de klant per jaar zonder vergoeding extra mag aflossen", "De omvang verschilt per aanbieder en wordt vaak uitgedrukt als percentage van de oorspronkelijke hoofdsom."], ["De periode na de akte waarin de klant de lening kosteloos kan opzeggen", "Dat is geen boetevrije ruimte; een bedenktijd geldt vóór het aangaan van de lening."], ["Het verschil tussen de marktwaarde en de hoogte van de lening", "Dat verschil is de overwaarde, niet de boetevrije ruimte."], ["Het deel van de lening dat aflossingsvrij mag blijven", "Aflossingsvrij is een aflossingsvorm; de boetevrije ruimte gaat over extra aflossen."]]],
["Een klant heeft een hypotheek met een oorspronkelijke hoofdsom van € 300.000 en mag jaarlijks 10% daarvan boetevrij aflossen. Hij lost dit jaar € 50.000 extra af. Over welk bedrag kan een vergoeding verschuldigd zijn?", [["€ 20.000", "Boetevrij is 10% van € 300.000 = € 30.000; over het meerdere van € 20.000 kan een vergoeding gelden."], ["€ 50.000", "Dat is het volledige extra bedrag; de boetevrije ruimte van € 30.000 moet eraf."], ["€ 45.000", "Dit gaat uit van 10% van het afgeloste bedrag in plaats van 10% van de oorspronkelijke hoofdsom."], ["€ 0, omdat extra aflossen altijd boetevrij is", "Extra aflossen boven de boetevrije ruimte is niet altijd boetevrij; dat hangt af van het renteverschil."]]],
["Een klant lost € 50.000 boven de boetevrije ruimte af. Zijn contractrente is 1 procentpunt hoger dan de actuele rente voor de resterende rentevaste periode van 4 jaar. Wat is het renteverlies zonder contantmaking?", [["€ 2.000", "€ 50.000 × 1% × 4 jaar = € 2.000; na contantmaking valt de werkelijke vergoeding iets lager uit."], ["€ 500", "Dit is het renteverlies van één jaar; er resteren nog vier jaar."], ["€ 5.000", "Dit gaat uit van 10 jaar of 10% in plaats van 1 procentpunt over 4 jaar."], ["€ 200", "Dit rekent met 0,1% in plaats van 1 procentpunt."]]],
["Waarom wordt het renteverlies bij de berekening van de vergoeding voor vervroegde aflossing contant gemaakt?", [["Omdat het renteverlies in de toekomst ligt", "Een toekomstig verlies is vandaag minder waard; contantmaking voorkomt dat de klant meer betaalt dan het werkelijke nadeel."], ["Omdat de vergoeding altijd contant bij de notaris moet worden betaald", "Contant maken is een rekenmethode, geen betaalwijze met contant geld."], ["Omdat de vergoeding anders onder de Wwft-meldplicht valt", "De Wwft heeft niets te maken met de berekeningsmethode van de vergoeding."], ["Omdat de vergoeding hierdoor fiscaal aftrekbaar wordt", "De fiscale behandeling hangt niet af van contantmaking."]]],
["Een klant overweegt tussentijds over te sluiten naar een lagere rente, maar moet daarvoor een vergoeding betalen. Wanneer is dat financieel zinvol?", [["Als het netto voordeel de vergoeding en kosten overtreft", "De klant moet het voordeel na belasting afzetten tegen de vergoeding, de advieskosten en eventuele notaris- en taxatiekosten."], ["Altijd, omdat een lagere rente op lange termijn altijd voordeliger is", "Een hoge vergoeding en bijkomende kosten kunnen het rentevoordeel volledig tenietdoen."], ["Alleen als de nieuwe rentevaste periode korter is dan de oude", "De lengte van de nieuwe periode bepaalt niet of oversluiten zinvol is; het gaat om de totale kosten en baten."], ["Alleen als de klant de vergoeding uit eigen geld kan betalen", "De vergoeding kan ook worden meegefinancierd; de vraag is of het voordeel opweegt tegen de kosten."]]],
["Waarom is het ESIS een gestandaardiseerd document?", [["Zodat aanbiedingen goed te vergelijken zijn", "Door de vaste opbouw staan rente, kosten en voorwaarden bij elke aanbieder op dezelfde plek."], ["Zodat de notaris de akte sneller kan opstellen", "Het ESIS is bedoeld voor de consument, niet als werkdocument voor de notaris."], ["Zodat de Belastingdienst de renteaftrek automatisch kan verwerken", "De Belastingdienst gebruikt het ESIS niet; renteaftrek loopt via de aangifte."], ["Zodat de adviseur geen eigen adviesrapport meer hoeft te maken", "Het ESIS vervangt het adviesrapport niet; het advies blijft een aparte verplichting."]]],
["Welk onderdeel vindt een consument in het ESIS terug?", [["Het totaal terug te betalen bedrag", "Het ESIS toont naast de rente en het JKP ook het totaal te betalen bedrag."], ["Het advies welke rentevaste periode het best bij hem past", "Het ESIS is productinformatie van de kredietgever, geen persoonlijk advies."], ["De taxatiewaarde van vergelijkbare woningen in de buurt", "Vergelijkbare verkopen staan in het taxatierapport, niet in het ESIS."], ["De hoogte van zijn toekomstige pensioenuitkering", "Pensioeninformatie staat in het pensioenoverzicht, niet in het ESIS."]]],
["Wat moet een hypotheekadviseur een klant vóór de dienstverlening verstrekken over zijn diensten en kosten?", [["De aard van de dienstverlening en de kosten", "De klant moet vooraf weten wat de adviseur doet, voor wie en wat het kost, om een bewuste keuze te maken."], ["Niets, kosten worden pas na afloop met de factuur gemeld", "Kosteninformatie moet juist vooraf worden gegeven, zodat de klant weet waar hij aan toe is."], ["Alleen het ESIS van de geldverstrekker", "Het ESIS gaat over het krediet, niet over de diensten en kosten van de adviseur."], ["Een overzicht van de provisie die hij van de geldverstrekker ontvangt", "Voor hypotheken geldt een provisieverbod; de klant betaalt de adviseur rechtstreeks."]]],
["Over welk diploma moet een adviseur die consumenten adviseert over hypothecair krediet in elk geval beschikken?", [["Het Wft-diploma Hypothecair Krediet", "Vakbekwaamheid vereist het passende Wft-diploma en het actueel houden van kennis via PE."], ["Een registratie als taxateur in het NRVT", "Een taxateur-registratie gaat over het waarderen van woningen, niet over hypotheekadvies."], ["Een notarieel getuigschrift", "Notarissen hebben een eigen opleiding; die is geen vakbekwaamheidseis voor adviseurs."], ["Alleen het Wft-diploma Basis is voldoende", "Basis is een onderdeel, maar voor hypotheekadvies is ook het diploma Hypothecair Krediet vereist."]]],
["Een klant is ontevreden over het hypotheekadvies en komt er met zijn adviseur niet uit. Waar kan hij met een klacht terecht?", [["Bij Kifid", "Een Wft-adviseur moet zijn aangesloten bij een erkende geschilleninstantie; voor financiële diensten is dat Kifid."], ["Bij FIU-Nederland", "FIU-Nederland ontvangt meldingen van ongebruikelijke transacties, geen klachten van consumenten."], ["Bij het Kadaster", "Het Kadaster houdt registers bij en behandelt geen klachten over advies."], ["Bij de Stichting WEW", "De Stichting WEW verstrekt NHG; zij beslist niet over geschillen tussen klant en adviseur."]]],
["Mag een consument een hypotheek afsluiten zonder advies (execution only)?", [["Ja, maar de kredietwaardigheidstoets blijft gelden", "Ook zonder advies blijft de verplichting om overkreditering te voorkomen bij de kredietgever liggen."], ["Nee, hypotheekadvies is voor consumenten wettelijk verplicht", "De wet verplicht niet tot advies; een consument mag zonder advies kiezen."], ["Ja, en dan vervalt ook de kredietwaardigheidstoets", "De toets geldt altijd, met of zonder advies."], ["Alleen als de hypotheek met NHG wordt afgesloten", "Execution only hangt niet af van NHG."]]],
["Een werknemer ontvangt jaarlijks een vaste, onvoorwaardelijke dertiende maand. Hoe telt die mee in het toetsinkomen?", [["Die telt volledig mee", "Vaste en onvoorwaardelijke componenten zoals een vaste eindejaarsuitkering horen bij het structurele inkomen."], ["Die telt niet mee, omdat hij maar eenmaal per jaar wordt uitbetaald", "Het moment van uitbetaling is niet bepalend; ook vakantiegeld wordt eenmaal per jaar betaald en telt mee."], ["Die telt alleen mee als de werkgever er een bonusreglement voor heeft", "Een vaste dertiende maand is geen bonus; een reglement is niet nodig als zij onvoorwaardelijk is."], ["Die telt mee, maar alleen voor de helft", "Een halvering kent de toets niet; een vast inkomensbestanddeel telt volledig mee."]]],
["Een klant ontvangt naast zijn salaris een prestatiebonus die elk jaar opnieuw wordt vastgesteld. Hoe gaan geldverstrekkers daar bij een werkgeversverklaring meestal mee om?", [["Een niet-gegarandeerde bonus telt in beginsel niet mee als vast inkomen", "Alleen structurele, vaste en onvoorwaardelijke componenten worden zonder meer meegeteld; een variabele bonus is onzeker."], ["De bonus telt altijd volledig mee, omdat hij het afgelopen jaar is uitbetaald", "Eén uitbetaling maakt een variabele bonus nog niet structureel."], ["De bonus telt dubbel mee om de onzekerheid van het basissalaris te compenseren", "Er is geen enkele reden om onzeker inkomen zwaarder te wegen; dat zou het risico vergroten."], ["De bonus verlaagt het toetsinkomen, omdat er meer belasting over wordt betaald", "Een bonus kan het inkomen niet verlagen; hij telt hooguit niet mee."]]],
["Bij een gepensioneerde aanvrager: wat vormt in de regel het toetsinkomen?", [["De AOW-uitkering en de pensioenuitkeringen", "Na de AOW-leeftijd bestaat het structurele inkomen uit AOW en (aanvullend) pensioen; daarvoor gelden aparte percentages."], ["Het laatstverdiende salaris vóór pensionering", "Dat salaris is er niet meer; de toets kijkt naar het huidige structurele inkomen."], ["Het vermogen in box 3 gedeeld door dertig", "Vermogen kan in het advies meewegen, maar is niet het standaard toetsinkomen."], ["Alleen het aanvullend pensioen, zonder AOW", "De AOW is een vast basisinkomen en telt mee in het toetsinkomen."]]],
["Een klant heeft een vast contract met een proeftijd die nog loopt. Waarom is dit relevant voor de hypotheekaanvraag?", [["Het dienstverband kan dan eenvoudig worden beëindigd", "Veel geldverstrekkers willen dat de proeftijd voorbij is of vragen een aanvullende verklaring van de werkgever."], ["Tijdens de proeftijd is het salaris belastingvrij", "Ook tijdens de proeftijd wordt over het salaris loonbelasting ingehouden."], ["Een proeftijd betekent dat het contract tijdelijk is", "Een vast contract blijft een vast contract, ook met een proeftijd."], ["Tijdens de proeftijd telt alleen het netto salaris mee", "De toets rekent met bruto inkomen; de proeftijd verandert dat niet."]]],
["Hoe telt een studieschuld bij DUO sinds 2024 mee in de leennormen?", [["Op basis van de werkelijke maandlast van de studieschuld", "De TRHK weegt sinds 2024 de actuele maandelijkse aflossing mee in plaats van een percentage van de oorspronkelijke schuld."], ["Op basis van een vast percentage van de oorspronkelijke studieschuld", "Dat was de methode tot 2024; nu is de werkelijke maandlast het uitgangspunt."], ["Niet, omdat DUO-schulden niet bij het BKR geregistreerd staan", "Ook al staat zij niet bij het BKR, de studieschuld telt wel mee; de klant moet haar opgeven."], ["Alleen als de klant een achterstand bij DUO heeft", "Ook zonder achterstand is de studieschuld een verplichting die meeweegt."]]],
["Een ongehuwd samenwonende klant zonder kinderen overlijdt. Waarom kan zijn partner dan in de regel niet rekenen op een Anw-uitkering?", [["Alleen bij een kind onder 18 of eigen arbeidsongeschiktheid", "Zonder jong kind of arbeidsongeschiktheid heeft een partner, geboren na 1949, geen recht op Anw."], ["De Anw geldt alleen voor gehuwde partners", "Ook samenwonenden met een gezamenlijke huishouding kunnen recht hebben; de voorwaarden zitten in kinderen en arbeidsongeschiktheid."], ["De Anw wordt alleen uitgekeerd als er een hypotheek met NHG is", "De Anw is een volksverzekering en staat los van de hypotheek."], ["De Anw-uitkering gaat altijd rechtstreeks naar de geldverstrekker", "De Anw wordt aan de nabestaande zelf betaald, als er recht op is."]]],
["Twee ongehuwd samenwonenden willen ieder het leven van de ander verzekeren met een overlijdensrisicoverzekering. Waarom adviseert men vaak 'kruislings' te verzekeren?", [["Zodat er geen erfbelasting over de uitkering wordt geheven", "Bij kruislings verzekeren is de begunstigde ook verzekeringnemer en premiebetaler; de uitkering is dan geen erfrechtelijke verkrijging."], ["Zodat de premie fiscaal aftrekbaar wordt in box 1", "ORV-premies zijn niet aftrekbaar, ook niet bij kruislings verzekeren."], ["Zodat beide partners een uitkering ontvangen bij één overlijden", "Er wordt maar op één leven uitgekeerd; kruislings gaat over wie de polis bezit."], ["Zodat de uitkering automatisch de hypotheek aflost via de notaris", "De uitkering gaat naar de begunstigde; aflossen is een keuze, geen automatisme via de notaris."]]],
["Een klant met een annuïtaire hypotheek wil een overlijdensrisicoverzekering. Welke dekkingsvorm sluit het meest aan bij het verloop van zijn schuld?", [["Een annuïtair dalende dekking", "Het verzekerd bedrag daalt dan in hetzelfde tempo als de restschuld, zodat de premie niet hoger is dan nodig."], ["Een gelijkblijvende dekking over de hele looptijd", "Dat past bij een aflossingsvrije lening; bij annuïtair aflossen wordt de klant op den duur oververzekerd."], ["Een lineair dalende dekking die in het begin snel daalt", "Een lineaire daling loopt in het begin sneller dan de annuïtaire schuld, waardoor er een tekort kan ontstaan."], ["Een stijgende dekking die met de inflatie meegroeit", "De schuld stijgt niet, dus een stijgende dekking voor de hypotheek is niet logisch."]]],
["Wat wordt bedoeld met het WGA-gat bij arbeidsongeschiktheid?", [["Een inkomensterugval na de loongerelateerde WGA-uitkering", "Wie zijn restverdiencapaciteit onvoldoende benut, valt terug op een uitkering op basis van het minimumloon, wat de woonlasten kan bedreigen."], ["De periode van twee jaar loondoorbetaling door de werkgever", "Loondoorbetaling gaat vooraf aan de WIA en is geen gat in het inkomen."], ["Het verschil tussen bruto en netto WGA-uitkering", "Dat is een gewoon belastingeffect, niet wat met het WGA-gat bedoeld wordt."], ["Het deel van het salaris boven het maximumdagloon", "Dat is het WIA-excedent, een ander risico dan het WGA-gat."]]],
["Een werknemer wordt werkloos en krijgt WW. Welk percentage van het (gemaximeerde) dagloon ontvangt hij?", [["De eerste twee maanden 75%, daarna 70%", "De WW start met 75% en daalt na twee maanden naar 70% van het dagloon, tot het maximumdagloon."], ["De hele duur 100% van het laatstverdiende loon", "De WW vervangt het loon slechts gedeeltelijk; volledige vervanging bestaat niet."], ["De eerste twee maanden 70%, daarna 75%", "De volgorde is andersom: de uitkering daalt na twee maanden."], ["Steeds 50%, ongeacht de duur", "Het percentage ligt hoger en verandert na twee maanden."]]],
["Welke verzekering keert maandelijks een bedrag uit om de woonlasten te betalen als de klant arbeidsongeschikt of werkloos wordt?", [["Een woonlastenverzekering", "Deze dekt de maandlasten voor een beperkte periode bij arbeidsongeschiktheid en/of werkloosheid."], ["Een opstalverzekering", "Een opstalverzekering dekt schade aan de woning, niet inkomensverlies."], ["Een overlijdensrisicoverzekering", "Een ORV keert alleen uit bij overlijden van de verzekerde."], ["Een rechtsbijstandsverzekering", "Rechtsbijstand helpt bij juridische geschillen, niet bij het betalen van de maandlasten."]]],
["Een klant koopt een woning met een hypotheek van 100% van de marktwaarde. Een paar jaar later dalen de huizenprijzen. Welk risico ontstaat?", [["Bij verkoop kan een restschuld ontstaan", "Bij onderwaarde dekt de verkoopopbrengst de schuld niet; dat beperkt ook de mogelijkheid om te verhuizen."], ["De rente wordt automatisch verhoogd tot het niveau van een consumptief krediet", "Een waardedaling leidt niet automatisch tot een consumptieve rente; hooguit kan een risico-opslag later hoger uitvallen."], ["De hypotheek wordt direct opeisbaar", "Een prijsdaling is geen opeisingsgrond zolang de klant aan zijn betalingen voldoet."], ["De renteaftrek vervalt, omdat de lening hoger is dan de woningwaarde", "Een waardedaling heeft geen invloed op de fiscale status van de eigenwoningschuld."]]],
["Een klant koopt een nieuwe woning voordat zijn oude woning is verkocht. Welk risico hoort de adviseur in elk geval te bespreken?", [["Dubbele woonlasten", "Hij betaalt dan voor twee woningen; duurt de verkoop lang of valt de opbrengst tegen, dan kan dat zijn budget uitputten."], ["Het verlies van zijn recht op NHG voor de nieuwe woning", "Een onverkochte oude woning sluit NHG niet automatisch uit."], ["Een hogere overdrachtsbelasting op de oude woning", "Overdrachtsbelasting betaalt de koper van de oude woning, niet de verkoper."], ["Het vervallen van de bedenktijd voor de nieuwe woning", "De bedenktijd hangt af van de koopakte, niet van de verkoop van de oude woning."]]],
["Waarom verdient funderingsrisico aandacht in het hypotheekadvies, bijvoorbeeld bij oudere woningen in veengebieden?", [["Herstel kan duur zijn en de waarde van de woning raken", "Funderingsproblemen kunnen tot hoge herstelkosten, waardedaling en problemen bij herfinanciering leiden."], ["Het verlaagt automatisch de hypotheekrente via de risicoklasse", "Funderingsrisico leidt niet tot een lagere rente; het vergroot juist het risico."], ["Het bepaalt de hoogte van de landelijke NHG-kostengrens", "De NHG-kostengrens is landelijk vastgesteld en staat los van individuele woningen."], ["Het is alleen relevant voor nieuwbouwwoningen", "Funderingsproblemen spelen juist bij oudere woningen met houten palen of op staal."]]],
["Een klant van 35 kiest voor een volledig annuïtaire hypotheek en heeft geen andere spaarbuffer. Wat is een belangrijk aandachtspunt in het advies?", [["Het belang van een financiële buffer", "Zonder buffer kunnen een kapotte cv-ketel of een tijdelijke inkomensdaling al tot achterstanden leiden."], ["Dat hij de hypotheek moet omzetten naar aflossingsvrij om sneller vermogen op te bouwen", "Aflossingsvrij bouwt geen vermogen op in de woning en geeft na 2012 geen renteaftrek."], ["Dat zijn renteaftrek na tien jaar vervalt", "De renteaftrek duurt maximaal 30 jaar, niet tien."], ["Dat hij verplicht een beleggingsverzekering naast de hypotheek moet nemen", "Een beleggingsverzekering is niet verplicht en past niet automatisch bij een annuïteit."]]],
["Op welke bepalingsmethode is het energielabel voor woningen sinds 2021 gebaseerd?", [["Op de NTA 8800", "Sinds 1 januari 2021 bepaalt een gecertificeerd energieadviseur het label volgens NTA 8800, op basis van het energiegebruik per vierkante meter per jaar."], ["Op de WOZ-waarde van de woning", "De WOZ-waarde is een fiscale waarde en zegt niets over de energieprestatie."], ["Op het gemiddelde gasverbruik van de vorige bewoners", "Het label hangt af van de woning zelf, niet van het verbruik van bewoners."], ["Op een zelfverklaring van de eigenaar via de gemeente", "Zelf invullen was vroeger mogelijk bij het voorlopig label; sinds 2021 bepaalt een energieadviseur het label."]]],
["Een klant wil zonnepanelen kopen en rekent op het salderen van teruggeleverde stroom. Wat moet de adviseur weten?", [["De salderingsregeling eindigt per 1 januari 2027", "Na afschaffing levert terugleveren minder op, wat de terugverdientijd van zonnepanelen verlengt."], ["Salderen is sinds 2020 een permanent wettelijk recht", "De salderingsregeling wordt juist beëindigd; zij is niet permanent."], ["Salderen geldt alleen bij een hypotheek met NHG", "Salderen hangt af van de energiewetgeving, niet van NHG."], ["De opbrengst van salderen verhoogt het toetsinkomen", "Besparingen op energie tellen niet als inkomen in de toets."]]],
["Wat is het Nationaal Warmtefonds?", [["Een fonds dat verduurzamingsleningen verstrekt", "Het fonds biedt onder meer de energiebespaarlening voor eigenaren-bewoners en VvE's."], ["Een fonds dat de energierekening van huishoudens met NHG vergoedt", "Het fonds vergoedt geen energierekeningen, maar financiert maatregelen."], ["Een verzekering tegen hoge stookkosten in de winter", "Het is geen verzekering, maar een financieringsfonds."], ["Een belasting op woningen met een slecht energielabel", "Het fonds heft geen belasting; het verstrekt leningen."]]],
["Een klant krijgt bij zijn geldverstrekker een rentekorting omdat zijn woning een goed energielabel heeft. Waarom bieden geldverstrekkers zo'n korting?", [["Omdat lagere energielasten de betaalbaarheid verbeteren", "Lagere woonlasten verbeteren de betaalbaarheid en duurzame woningen houden vaak beter hun waarde; aanbieders willen verduurzaming ook stimuleren."], ["Omdat de TRHK zo'n korting voor alle aanbieders verplicht stelt", "De TRHK geeft extra leenruimte bij een goed label, maar verplicht geen rentekorting."], ["Omdat de Stichting WEW de korting vergoedt", "De Stichting WEW verstrekt NHG en vergoedt geen rentekortingen."], ["Omdat een goed label de renteaftrek verhoogt", "De renteaftrek hangt niet af van het energielabel."]]],
["Een klant wil een warmtepomp laten plaatsen, die hij met zijn hypotheek financiert. Hoe kan het leningdeel fiscaal worden behandeld?", [["Als eigenwoningschuld, want het verbetert de woning", "Uitgaven voor verbetering van de eigen woning kunnen eigenwoningschuld zijn als aan de aflossingseis wordt voldaan."], ["Als box 3-schuld, omdat een warmtepomp een roerende zaak is", "Een vast aangebrachte installatie verbetert de woning en kan in de eigenwoningschuld vallen."], ["Als consumptief krediet zonder fiscale gevolgen", "Financiering via de hypotheek voor woningverbetering kan juist wel eigenwoningschuld zijn."], ["De rente is dubbel aftrekbaar vanwege de duurzaamheid", "Er bestaat geen dubbele aftrek voor duurzame investeringen."]]],
["Een klant neemt een hypotheek in een vreemde valuta. Wat regelt de hypothekenrichtlijn (MCD) hierover?", [["Waarborgen tegen wisselkoersrisico, zoals omzetting", "Valutaleningen kunnen bij koersschommelingen sterk duurder worden; de MCD vereist daarom waarborgen."], ["Valutaleningen zijn in de hele EU verboden", "De MCD verbiedt ze niet, maar stelt eisen aan bescherming en informatie."], ["De geldverstrekker draagt altijd zelf het volledige koersverlies", "Het risico ligt in beginsel bij de consument; de MCD beperkt dat met waarborgen."], ["Valutaleningen vallen buiten de richtlijn", "Ze vallen er juist onder, met extra regels."]]],
["Wat verwacht de hypothekenrichtlijn (MCD) van kredietgevers als een consument betalingsachterstanden heeft?", [["Redelijke clementie vóór executie", "De richtlijn vraagt aanbieders eerst te zoeken naar oplossingen, zoals een betalingsregeling, voordat ze executeren."], ["Direct executeren om verdere achterstanden te voorkomen", "Onmiddellijk executeren is in strijd met de gedachte van clementie in de richtlijn."], ["De rente verdubbelen tot de achterstand is ingelopen", "Een strafrente verdubbelen helpt de consument niet en past niet bij de richtlijn."], ["De achterstand melden bij FIU-Nederland", "Een betalingsachterstand is geen ongebruikelijke transactie in de zin van de Wwft."]]],
["Wanneer mag een hypotheekadviseur zich 'onafhankelijk' noemen?", [["Als hij ruim vergelijkt en geen beloning van aanbieders ontvangt", "Deze eis komt uit de hypothekenrichtlijn: onafhankelijkheid vereist een ruime marktvergelijking en geen beloning van aanbieders."], ["Als hij bij geen enkele geldverstrekker in dienst is", "Niet in dienst zijn is niet genoeg; hij moet ook voldoende producten vergelijken."], ["Als hij een bord 'onafhankelijk' aan de gevel van zijn kantoor heeft", "De term is wettelijk beschermd en vraagt meer dan een eigen verklaring."], ["Als hij alleen met de drie grootste banken werkt", "Drie aanbieders is geen voldoende aantal producten voor een ruime marktvergelijking."]]],
["Een reclame voor hypotheken noemt een rentepercentage. Wat vereisen de regels op grond van de hypothekenrichtlijn?", [["Standaardinformatie met een representatief voorbeeld", "Wie in reclame rente of kosten noemt, moet ook informatie geven zoals het JKP met een representatief voorbeeld."], ["Dat de AFM de reclame vooraf heeft goedgekeurd", "De AFM keurt reclame niet vooraf goed; zij houdt achteraf toezicht."], ["Dat het rentepercentage minimaal een jaar geldig blijft", "Zo'n eis bestaat niet voor reclame."], ["Dat de reclame alleen online mag verschijnen", "Er is geen beperking tot online reclame."]]],
["Wanneer moet een Wwft-instelling een ongebruikelijke transactie melden bij FIU-Nederland?", [["Onverwijld", "De meldplicht geldt direct; wachten tot het dossier is afgerond is niet toegestaan."], ["Binnen een jaar na afronding van de transactie", "Zo'n ruime termijn kent de Wwft niet."], ["Alleen als de klant daarmee akkoord gaat", "De klant mag juist niet over de melding worden geïnformeerd."], ["Pas als er een strafrechtelijke veroordeling is", "Melden is preventief; een veroordeling is geen voorwaarde."]]],
["Hoe lang moet een Wwft-instelling de gegevens uit het cliëntenonderzoek bewaren?", [["Vijf jaar na het einde van de relatie", "De Wwft schrijft een bewaartermijn van vijf jaar voor, gerekend vanaf het einde van de relatie."], ["Eén jaar na het eerste contact met de klant", "Dat is te kort en heeft een verkeerd startmoment."], ["Zeven jaar na aanvang van de relatie", "Zeven jaar is de fiscale bewaarplicht met een ander startpunt."], ["Tot de klant overlijdt", "De Wwft kent een vaste termijn, geen termijn tot overlijden."]]],
["Een klant die een hypotheek aanvraagt, blijkt een politiek prominent persoon (PEP) te zijn. Wat geldt?", [["Verscherpt cliëntenonderzoek", "Bij een PEP is het risico op corruptie hoger; de instelling moet extra maatregelen nemen."], ["De aanvraag moet worden geweigerd", "Dienstverlening aan een PEP is toegestaan, mits met verscherpte maatregelen."], ["Vereenvoudigd cliëntenonderzoek is voldoende", "Een PEP brengt juist een hoger risico mee, dus vereenvoudigd onderzoek past niet."], ["Er is geen cliëntenonderzoek nodig vanwege de publieke functie", "Een publieke functie verkleint het risico niet; cliëntenonderzoek blijft verplicht."]]],
["Welke twee soorten indicatoren gebruikt een Wwft-instelling om te bepalen of een transactie ongebruikelijk is?", [["Objectieve en subjectieve indicatoren", "Objectieve indicatoren verplichten tot melden bij bepaalde feiten; subjectieve vragen een eigen beoordeling of er aanleiding is."], ["Fiscale en civiele indicatoren", "Deze indeling bestaat niet in de Wwft."], ["Interne en externe indicatoren", "Dat is geen indeling die de Wwft hanteert."], ["Nationale en Europese indicatoren", "De Wwft kent deze indeling niet; het gaat om objectief en subjectief."]]],
["Een medewerker meldt te goeder trouw een ongebruikelijke transactie bij FIU-Nederland. Later blijkt er niets aan de hand. Wat geldt?", [["Hij is gevrijwaard van aansprakelijkheid", "De Wwft vrijwaart melders te goeder trouw, zodat zij niet worden ontmoedigd om te melden."], ["Hij moet de klant een schadevergoeding betalen", "De vrijwaring beschermt de melder te goeder trouw tegen aansprakelijkheid."], ["Hij moet de klant alsnog over de melding inlichten", "Ook achteraf geldt de geheimhoudingsplicht."], ["Hij krijgt een boete van de AFM voor een onterechte melding", "Een melding te goeder trouw is nooit strafbaar."]]],
["Een klant stort contant geld op zijn rekening, maakt het over naar familie in het buitenland en gebruikt het later als eigen inbreng voor een woning. In welke fase van witwassen is het contante geld op de rekening gezet?", [["De plaatsingsfase", "In de plaatsingsfase wordt crimineel geld in het financiële systeem gebracht, bijvoorbeeld door contant te storten."], ["De integratiefase", "Integratie is het gebruiken van witgewassen geld in de legale economie, zoals bij de aankoop van de woning."], ["De versluieringsfase", "Versluiering is het verhullen van het spoor, zoals de overboekingen naar het buitenland."], ["De beleggingsfase", "Een beleggingsfase bestaat niet in het klassieke model van witwassen."]]],
["Wat moet een financiële onderneming naast de Wwft controleren op grond van de Sanctiewet 1977?", [["Of klanten op sanctielijsten staan", "Bij een treffer moeten tegoeden worden bevroren en mag geen dienstverlening plaatsvinden."], ["Of klanten een Verklaring Omtrent het Gedrag hebben", "Een VOG vraagt de werkgever van medewerkers, niet van klanten."], ["Of klanten een BKR-registratie hebben", "BKR-toetsing hoort bij kredietverlening, niet bij de Sanctiewet."], ["Of klanten een testament hebben opgesteld", "Dat is geen onderdeel van de Sanctiewet."]]],
["Een klant wil voor de hypotheekaanvraag geen identiteitsbewijs laten zien. Wat moet de Wwft-instelling doen?", [["De relatie niet aangaan", "Zonder vastgestelde en geverifieerde identiteit mag de instelling geen relatie aangaan en moet zij overwegen te melden."], ["De aanvraag verwerken en de identificatie later inhalen", "Identificatie moet in beginsel vooraf plaatsvinden; zonder kan de relatie niet starten."], ["Volstaan met een kopie van een energierekening", "Een energierekening bewijst geen identiteit."], ["De klant doorverwijzen naar de notaris, die de identificatie overneemt", "De instelling moet zelf aan haar plicht voldoen."]]],
["Ouders kopen een appartement dat hun studerende dochter gaat bewonen; de ouders blijven zelf in hun eigen huis wonen. Welk tarief overdrachtsbelasting geldt voor de ouders?", [["Het hogere tarief voor niet-eigen bewoning", "Het verlaagde tarief en de startersvrijstelling gelden alleen voor een koper die de woning zelf als hoofdverblijf gaat bewonen."], ["Het verlaagde tarief, omdat een familielid er gaat wonen", "Bewoning door een kind telt niet; de koper zelf moet er gaan wonen."], ["De startersvrijstelling, omdat de dochter jonger is dan 35 jaar", "De vrijstelling kijkt naar de leeftijd en bewoning van de koper, niet van het kind."], ["Geen overdrachtsbelasting, omdat het om studentenhuisvesting gaat", "Er is geen vrijstelling voor woningen die studenten bewonen."]]],
["Een klant heeft een overbruggingskrediet op zijn oude woning, die langer te koop staat dan verwacht. Wat is een belangrijk risico?", [["De overbrugging loopt af vóór de verkoop", "Overbruggingskredieten hebben een beperkte looptijd; blijft verkoop uit, dan lopen lasten en onzekerheid op."], ["De overbrugging wordt automatisch omgezet in een starterslening", "Een starterslening is een aparte regeling en ontstaat niet uit een overbrugging."], ["De renteaftrek op de nieuwe woning vervalt direct", "De aftrek voor de nieuwe woning blijft gewoon bestaan."], ["De nieuwe woning moet worden teruggegeven aan de verkoper", "De koop van de nieuwe woning staat vast; een trage verkoop maakt die niet ongedaan."]]],
["Een klant vraagt of de geldverstrekker zijn hypotheekrente mag verhogen tijdens een lopende rentevaste periode. Wat is in beginsel juist?", [["Nee, tijdens de rentevaste periode staat de afgesproken rente vast", "Dat is precies de zekerheid die de klant met een rentevaste periode koopt."], ["Ja, als de marktrente stijgt mag de bank de rente direct aanpassen", "Dat geldt bij een variabele rente, niet bij een vaste rente."], ["Ja, maar alleen eenmaal per jaar met maximaal één procentpunt", "Zo'n regel bestaat niet voor vaste rentes."], ["Ja, als de AFM-toetsrente stijgt", "De toetsrente is een toetsingscijfer en verandert de contractrente niet."]]],
["Een klant heeft twee leningdelen: een annuïtair deel en een lineair deel. Wat is juist over de fiscale aflossingseis?", [["Beide voldoen aan de aflossingseis", "De aflossingseis vraagt minimaal annuïtair in 30 jaar; lineair lost sneller af en voldoet dus ook."], ["Alleen het annuïtaire deel voldoet aan de aflossingseis", "Lineair aflossen voldoet ook, omdat het sneller gaat dan annuïtair."], ["Alleen het lineaire deel voldoet, omdat annuïtair te traag aflost", "Annuïtair in 30 jaar is precies de minimumeis."], ["Geen van beide, omdat combinaties niet zijn toegestaan", "Combinaties van leningdelen zijn gewoon mogelijk."]]],
["Een klant wil zijn woning tijdelijk verhuren tijdens een werkperiode in het buitenland. Wat moet hij volgens de gangbare hypotheekvoorwaarden doen?", [["Vooraf toestemming vragen aan de geldverstrekker", "Verhuur raakt de zekerheid van de geldverstrekker; de voorwaarden en het huurbeding vragen daarom voorafgaande toestemming."], ["Niets, verhuur van een eigen woning is altijd vrij toegestaan", "Hypotheekvoorwaarden beperken verhuur zonder toestemming, juist om de waarde van het onderpand te beschermen."], ["De verhuur alleen melden bij de gemeente waar de woning staat", "Een melding bij de gemeente vervangt de toestemming van de geldverstrekker niet."], ["De hypotheek eerst volledig oversluiten naar een andere geldverstrekker", "Oversluiten is niet nodig; de klant moet toestemming vragen aan zijn huidige geldverstrekker."]]],
["Een klant woont in een woning op erfpachtgrond en betaalt jaarlijks canon. Hoe wordt die canon in de inkomstenbelasting behandeld?", [["Die is aftrekbaar in box 1", "Naast de hypotheekrente kunnen periodieke erfpachtbetalingen voor de eigen woning in box 1 worden afgetrokken."], ["De canon is niet aftrekbaar, omdat het een vorm van huur is", "Fiscaal geldt de periodieke canon voor de eigen woning juist als aftrekbare kosten, net als rente."], ["De canon verhoogt het eigenwoningforfait met hetzelfde bedrag", "De canon heeft geen invloed op het forfait; dat blijft een percentage van de WOZ-waarde."], ["De canon valt als schuld in box 3 van de erfpachter", "Een periodieke betaling is geen schuld; de canon is een aftrekpost in box 1."]]],
["Wat is een UBO in de zin van de Wwft?", [["De uiteindelijk belanghebbende van een organisatie", "Als hoofdregel is dat wie meer dan 25% eigendom of zeggenschap heeft; bij cliëntenonderzoek naar een rechtspersoon moet de instelling de UBO vaststellen."], ["De compliance officer die bij een bank de naleving bewaakt", "Een compliance officer bewaakt de naleving, maar is geen uiteindelijk belanghebbende."], ["Een type beleggingsfonds voor vastgoed", "UBO is geen productsoort maar een begrip voor de uiteindelijke eigenaar of zeggenschapper."], ["De toezichthouder op trustkantoren", "Op trustkantoren houdt DNB toezicht; UBO staat voor Ultimate Beneficial Owner."]]]
];
